      skills: ['recog', 'listen', 'produce'],
      faces: ['R1', 'R2', 'R3', 'R4', 'R5', 'R6', 'L1', 'L2', 'L3', 'P1', 'P2', 'P3', 'P5', 'P6'],
      english: 'back', furiganaFront: 'unknown', answerMode: 'mixed', audio: { front: 'listen', back: 'auto' },
