    index?.schemaVersion !== 3 ||
    index?.shardCount !== 16 ||
    index?.sharding?.id !== 'fnv1a32-ascii-seq-mask15' ||
    index.sharding.shardCount !== index.shardCount ||
    (mode === 'main' && !mainEntries) ||
    (mode === 'worker' && mainEntries)
