  learningSourceVisit = options.visit || null;
  keepScroll();
  S.publisherReceipt = receiptSha256;
  S.publisherContextReturn = options.context || null;
  S.publisherScroll = S.readerPos[`publisher:${receiptSha256}`] || 0;
  S.view = 'publisher';
  render();
