  let best = null;
  for (const p of pool) {
    const count = mine.size ? (p.readingFacets?.forms || []).filter((f) => mine.has(f)).length : 0;
    if (!best || count > best.count || (count === best.count && byNewest(p, best.passage) < 0)) best = { passage: p, count };
  }
