  const ownsSurface = () => recordWritable(epoch) && controller === teacherDraftController &&
    serial === teacherContextSelectionSerial && S.view === 'sentence-practice' && S.sentencePracticeView === state &&
    surface?.isConnected && !S.stack.length;
