/** 稽古の間 — the study hall (operator, 2026-09-18: "we should have a whole
 * corpus of test from JLPT levels and others, as well as SRS cards. and other
 * options to study here. not sure where they are… please check"). Every study
 * room the app has, behind one door each, with an honest count; what is NOT in
 * the app yet is named, not implied.
 *
 * Learn lane (2026-10-08, concept C "the stage" + A's numbered sections; John:
 * "No clusters like the dojo page having everything strewn together"). The
 * room is one stage and five numbered, distinct blocks:
 *   the stage — the next sitting: one lit card, the real due count, the deck
 *               split and ONE primary (the 復習 door, or a deck when none wait)
 *   01 guided · 02 decks · 03 focus (the pinned [data-learn-section] order)
 *   04 tests · 05 more practice
 * #study-hall wraps the five blocks, so every hall door (≥6) is inside it. */
function learnTestCounts() {
  const mockCount = Array.isArray(D.mock) ? D.mock.length : null;
  if (mockCount === null) ensureMockIndex().then(() => { if (S.view === 'dojo') render(); }).catch(() => {});
  if (!assessmentCatalog && !assessmentOpening) {
    assessmentOpening = true;
    loadAssessmentCatalog().then(() => { if (S.view === 'dojo') render(); }).catch(() => {}).finally(() => { assessmentOpening = false; });
  }
  const ready = (assessmentCatalog?.entries || []).filter((entry) => entry.availability?.ready);
  return {
    tests: ready.filter((entry) => !['section', 'written'].includes(entry.mode)).length,
    sections: ready.filter((entry) => entry.mode === 'section').length,
    // machine-checked written tests are counted apart: they have no length and still await review
    written: ready.filter((entry) => entry.mode === 'written').length,
    loaded: !!assessmentCatalog,
  };
}

/** The study hall's doors, by id: the same seven rooms and the same entries as ever. */
function studyHallDoors() {
  const due = S.taken.length && scheduler ? todayQueue().order.length : 0;
  const { tests: readyTests, sections: readySections, written: readyWritten } = learnTestCounts();
  const defs = [
    ['review', '復習', 'SRS cards', due ? tx(`${due} 枚 待っている`, `${due} card${due === 1 ? '' : 's'} waiting`) : tx('待っている札はない', 'no cards waiting'), () => {
      keepScroll(); S.stack = []; S.trayFrom = { view: 'dojo', scroll: 0 }; S.view = 'tray'; render(); window.scrollTo(0, 0);
    }],
    ['mock', 'JLPT 模試・練習', 'JLPT tests & practice', readyTests
      ? tx(`${readyTests}組 · 級と長さを選ぶ`, `${readyTests} tests · choose a level and length`)
      : readyWritten ? tx(`筆記テスト ${readyWritten}組 · 検収前`, `${readyWritten} written tests · awaiting review`)
      : readySections ? tx(`${readySections}組の練習 · 模試は準備中`, `${readySections} practice set${readySections === 1 ? '' : 's'} · mock tests in preparation`)
        : tx('新しい模試を準備中 · 以前の練習も使えます', 'New mocks in preparation · earlier exercises available'), () => {
      keepScroll(); S.view = 'mock'; render(); window.scrollTo(0, 0);
    }],
    ['guided', '案内つきの稽古', 'a guided session', tx('N2 筆記 6問 · 約15分 · 解説と語の扉つき', 'N2 written · 6 questions · about 15 min · explanations and word doors'),
      () => openGuidedRoom('dojo')],
    ['lessons', 'レッスン', 'lessons', tx('語彙の稽古', 'vocabulary lessons'), () => {
      keepScroll(); S.view = 'lessons'; render(); window.scrollTo(0, 0);
    }],
    ['sentence', '文の練習', 'sentence practice', tx('保存した文で作る', 'from the sentences you saved'), () => {
      keepScroll(); S.view = 'sentence-practice'; render(); window.scrollTo(0, 0);
    }],
    ['probe', '読み探査', 'yomi probe', tx('まだ取っていない熟語を測る', 'sound out compounds you never took'), () => {
      S.focusMode = 'yomi'; render(); window.scrollTo(0, 0);
    }],
    ['levels', '参考書庫', 'reference library', tx('JLPT・漢検の一覧', 'JLPT and Kanji Kentei lists'), () => {
      keepScroll(); pendingReferenceCollection = null; referenceLibrary?.reset(); S.view = 'levels'; render(); window.scrollTo(0, 0);
    }],
  ];
  const doors = {};
  for (const [id, ja, en, sub, go] of defs) {
    const b = el('button', 'study-door');
    b.type = 'button';
    b.dataset.studyDoor = id;
    b.append(el('span', 'study-door-t', tx(ja, en)));
    b.append(el('span', 'study-door-sub', sub));
    b.addEventListener('click', go);
    doors[id] = b;
  }
  doors.due = due;
  return doors;
}

/** A numbered block head (A's numbered sections, C's 01 in the gutter): the
 * number, the name, and one live count on the right when there is one. */
function learnHead(n, ja, en, count) {
  const head = el('header', 'learn-head');
  const num = el('span', 'learn-n', n);
  num.setAttribute('aria-hidden', 'true');
  head.append(num, el('h2', 'learn-h', tx(ja, en)));
  if (count) head.append(el('span', 'learn-count', count));
  return head;
}

/* the stage's split names the three passage decks in short */
const LEARN_STAGE_DECKS = [['n2', 'N2', 'N2'], ['n1', 'N1', 'N1'], ['senmon', '専門', 'Fields']];
const deckSummaryPending = new Set();
/** A deck's live counts ({ due, fresh, words }), or null while they load (one load per deck). */
function learnDeckSummary(id) {
  const sum = deckSummaries[id];
  if (sum || window.__CORRIDOR_STANDALONE__ === true || deckSummaryPending.has(id)) return sum || null;
  deckSummaryPending.add(id);
  loadDeckPlayer()
    .then((mod) => mod.summary(id))
    .then((got) => {
      deckSummaries[id] = got;
      if (S.view === 'dojo') render();
    })
    .catch(() => {})
    .finally(() => deckSummaryPending.delete(id));
  return null;
}

let learnStageAsked = null;
/** The lit card's face, front-safe (zero-leak): the first waiting word or
 * kanji of today's queue, shown the way its own front would be — inside its
 * saved sentence with the word blanked, or bare. No reading, no meaning, no
 * answer, nothing to tap. Returns null while the sentence's article loads. */
function learnStageFace(order) {
  const item = order.find((it) => it.t === 'word' || it.t === 'kanji');
  if (!item) return { item: null };
  if (item.t === 'word' && item.ctx) {
    const cloze = takenContext(item);
    if (!cloze) {
      const p = D.passages.find((x) => x.id === item.ctx.p);
      if (p && !p.tokens && learnStageAsked !== p.id) {
        learnStageAsked = p.id;
        ensureArticle(p).then(() => { if (S.view === 'dojo') render(); }).catch(() => {});
      }
      return p && !p.tokens ? null : { item, label: item.label || item.id };
    }
    const parts = [];
    let text = '';
    let seen = 0;
    for (const token of cloze.tokens) {
      if (token.b === item.id) {
        parts.push({ text, at: seen });
        text = '';
        seen += 1;
      } else text += token.s;
    }
    if (seen) {
      parts.push({ text, at: -1 });
      // open just before the asked place: the gap stays on the card's first lines
      if (parts[0].text.length > 30) parts[0].text = `…${parts[0].text.slice(-26)}`;
      return { item, parts, source: cloze.source };
    }
  }
  return { item, label: item.label || item.id };
}

let learnStageSeen = 0;
let learnStageArrived = 0;
/** The stage (concept C): a lacquer proscenium holding one lit washi card. */
function renderLearnStage(main, doors) {
  const stage = el('section', 'learn-stage');
  stage.setAttribute('aria-labelledby', 'learn-stage-title');
  // the signature plays once per arrival: a re-render inside the beat (counts
  // landing) continues it from where it is, through a negative delay
  const now = Date.now();
  if (now - learnStageSeen > 1500) learnStageArrived = now;
  learnStageSeen = now;
  if (now - learnStageArrived < 700) {
    stage.classList.add('is-arriving');
    stage.style.setProperty('--learn-t', `${learnStageArrived - now}ms`);
  }
  const head = el('header', 'learn-stage-head');
  head.append(el('p', 'learn-stage-eyebrow', tx('学ぶ・次の稽古', 'Learn · the next sitting')));
  const title = el('h1', 'view-title', tx('舞台', 'The stage'));
  title.id = 'learn-stage-title';
  head.append(title);
  stage.append(head);

  const due = doors.due;
  const order = due ? todayQueue().order : [];
  const face = due ? learnStageFace(order) : { item: null };
  const fan = el('div', 'learn-fan');
  for (const k of [0, 1]) {
    const ghost = el('span', `learn-ghost g${k}`);
    ghost.setAttribute('aria-hidden', 'true');
    fan.append(ghost);
  }
  const card = el('div', 'learn-card');
  for (const corner of ['tl', 'tr', 'bl', 'br']) {
    const reg = el('i', `learn-reg ${corner}`);
    reg.setAttribute('aria-hidden', 'true');
    card.append(reg);
  }
  const meta = el('p', 'learn-card-meta');
  const text = el('p', 'learn-card-text');
  if (face?.parts) {
    meta.textContent = tx('次の札 · 保存した文から', 'next card · your sentence');
    text.lang = 'ja';
    text.dataset.uiContent = 'learning';
    for (const part of face.parts) {
      if (part.text) text.append(document.createTextNode(part.text));
      if (part.at >= 0) {
        const gap = el('span', 'learn-gap', '　　');
        gap.setAttribute('aria-label', tx('空欄', 'blank'));
        text.append(gap);
      }
    }
  } else if (face?.label) {
    meta.textContent = face.item.t === 'kanji' ? tx('次の札 · 漢字', 'next card · kanji') : tx('次の札 · 語', 'next card · word');
    text.classList.add('is-word');
    text.lang = 'ja';
    text.dataset.uiContent = 'learning';
    text.textContent = face.label;
  } else if (due) {
    meta.textContent = tx('次の札', 'next card');
    text.classList.add('is-quiet');
    text.textContent = face === null ? tx('文を開いています…', 'Opening its sentence…') : tx('札はリストで待っている。', 'Your cards wait on the list.');
  } else {
    meta.textContent = tx('今日', 'today');
    text.classList.add('is-quiet');
    text.textContent = tx('待っている札はない。', 'No saved card is waiting.');
  }
  card.prepend(meta);
  card.append(text);
  fan.append(card);
  stage.append(fan);

  // the count and the split: the big number is the sitting the primary opens
  // (todayQueue, the Line's own number); the decks keep their own ledgers, so
  // their split is named apart and never added in
  const row = el('div', 'learn-stage-row');
  const count = el('p', 'learn-due');
  count.append(el('b', 'learn-due-n', String(due)));
  count.append(el('span', 'learn-due-u', tx('枚 復習待ち', due === 1 ? 'card due today' : 'cards due today')));
  row.append(count);
  const sums = LEARN_STAGE_DECKS.map(([id, ja, en]) => [id, tx(ja, en), learnDeckSummary(id)]);
  const loaded = sums.filter(([, , sum]) => sum);
  if (loaded.length) {
    const anyDue = loaded.some(([, , sum]) => sum.due);
    const split = el('p', 'learn-split');
    split.append(el('span', 'learn-split-h', anyDue ? tx('デッキの復習', 'decks · due') : tx('デッキの新しい札', 'decks · new')));
    const line = el('span', 'learn-split-line');
    for (const [id, name, sum] of loaded) {
      const cell = el('span', 'learn-split-cell');
      cell.dataset.stageDeck = id;
      cell.append(el('span', 'learn-split-name', name), el('b', 'learn-split-n', String(anyDue ? sum.due : sum.fresh)));
      line.append(cell);
    }
    split.append(line);
    row.append(split);
  }
  stage.append(row);

  // ONE primary. When saved cards wait, it is the 復習 door (to Today's list,
  // as it always was). When none wait, the deck with the most due — or new —
  // passages leads, and the 復習 door stays as a quiet line under it.
  const review = doors.review;
  review.classList.add('learn-go');
  if (due) {
    review.querySelector('.study-door-t').textContent = tx(`${due} 枚を復習する`, `Review ${due} card${due === 1 ? '' : 's'}`);
    review.querySelector('.study-door-sub').textContent = tx('今日のリストから始める', 'starts from today’s list');
    stage.append(review);
  } else {
    const best = loaded.slice().sort((a, b) => b[2].due - a[2].due || b[2].fresh - a[2].fresh)[0];
    if (best && (best[2].due || best[2].fresh)) {
      const [id, short, sum] = best;
      const go = el('button', 'learn-go learn-go-deck');
      go.type = 'button';
      go.dataset.stageDeck = id;
      go.append(el('span', 'learn-go-t', sum.due
        ? tx(`${short}の ${sum.due} 枚を復習する`, `Review ${sum.due} ${short} card${sum.due === 1 ? '' : 's'}`)
        : tx(`${short}の新しい札 ${sum.fresh} 枚を始める`, `Begin ${sum.fresh} new ${short} card${sum.fresh === 1 ? '' : 's'}`)));
      go.addEventListener('click', () => openDeck(id));
      stage.append(go);
      review.classList.replace('learn-go', 'learn-go-quiet');
    }
    stage.append(review);
  }
  main.append(stage);
}

/** The five numbered blocks under the stage, inside #study-hall. */
function renderStudyHall(main, doors) {
  const hall = el('div', 'learn-hall');
  hall.id = 'study-hall';

  const guided = el('section', 'learn-section');
  guided.dataset.learnSection = 'guided';
  guided.append(learnHead('01', '案内つき', 'Guided', tx('6問 · 約15分', '6 questions · ~15 min')));
  guided.append(el('p', 'learn-gloss', tx('問いごとに解説と語の扉。迷ったらここから。', 'An explanation after every question, a door to every word. Start here when unsure.')));
  guided.append(doors.guided);

  const decks = el('section', 'learn-section');
  decks.dataset.learnSection = 'decks';
  renderDojoDecks(decks);

  const focus = el('section', 'learn-section');
  focus.dataset.learnSection = 'focus';
  renderFocusSitting(focus);

  const tests = el('section', 'learn-section learn-tests');
  const counts = learnTestCounts();
  const total = counts.tests + counts.sections + counts.written;
  tests.append(learnHead('04', '試験', 'Tests', counts.loaded ? tx(`${total} 組`, `${total} set${total === 1 ? '' : 's'}`) : ''));
  tests.append(doors.mock);
  // the lengths a mock comes in, with how many of each are ready — the catalog's own numbers
  const entries = assessmentCatalog?.entries || [];
  const lengths = el('div', 'learn-lengths');
  for (const [mode, ja, en] of [['short', '短め', 'Short'], ['medium', '中', 'Medium'], ['full', '本番', 'Full']]) {
    const rows = entries.filter((entry) => entry.mode === mode);
    if (!rows.length) continue;
    const readyN = rows.filter((entry) => entry.availability?.ready).length;
    const minutes = rows.map((entry) => entry.durationMinutes).filter(Number.isFinite);
    const cell = el('p', 'learn-length' + (readyN ? '' : ' is-pending'));
    cell.dataset.mockMode = mode;
    cell.append(el('b', 'learn-length-t', tx(ja, en)));
    if (minutes.length) cell.append(el('span', 'learn-length-m', tx(`${Math.min(...minutes)} 分`, `${Math.min(...minutes)} min`)));
    cell.append(el('span', 'learn-length-n', readyN ? tx(`${readyN} 組`, `${readyN} ready`) : tx('準備中', 'in preparation')));
    lengths.append(cell);
  }
  if (lengths.childNodes.length) tests.append(lengths);
  tests.append(el('p', 'fine study-hall-note', tx(
    '模試で見つけた課題は、覚えるリスト・復習・先生との学習につながります。',
    'Use your test results to guide Learn, review cards and your next session with Sensei.',
  )));

  const more = el('section', 'learn-section learn-more');
  more.append(learnHead('05', 'ほかの稽古', 'More practice', ''));
  const list = el('div', 'learn-more-list');
  list.append(doors.lessons, doors.sentence, doors.probe, doors.levels);
  more.append(list);

  hall.append(guided, decks, focus, tests, more);
  main.append(hall);
}

/** The dojo lobby: choose a length and what to drill. */
/* 集中道場 › デッキ — the SRS decks the learner can sit. Each deck keeps its
 * own schedule (its own localStorage ledger); 覚えるの札 is the corridor's
 * own word queue, opened as a plain review. */
const DOJO_DECKS = [{ id: 'n2', ja: 'N2・文章で覚える', en: 'N2 vocabulary · passages' }, { id: 'n1', ja: 'N1・文章で覚える', en: 'N1 vocabulary · passages' }, { id: 'senmon', ja: '専門・五つの分野', en: 'Your five fields · master’s level' }, { id: 'kotoba-mcd', ja: '言葉の鉱脈・MCD', en: 'massive-context cloze · real and written passages' }, { id: 'kotoba-mine', ja: '言葉の鉱脈・文', en: 'real sentences · read and recall' }];
let deckPlayer = null;
let deckPlayerLoading = null;
let deckPlayerError = false;
const deckSummaries = {};
function loadDeckPlayer() {
  if (deckPlayer) return Promise.resolve(deckPlayer);
  if (!deckPlayerLoading) {
    deckPlayerLoading = Promise.all([import('./decks/player/mount.js'), loadDeckHost()]).then(([mod]) => mod).then(
      (mod) => {
        deckPlayer = mod;
        return mod;
      },
      (err) => {
        deckPlayerError = true;
        deckPlayerLoading = null;
        throw err;
      },
    );
  }
  return deckPlayerLoading;
}

function openDeck(id) {
  keepScroll();
  S.deckPlay = id;
  S.view = 'deckplay';
  render();
  window.scrollTo(0, 0);
}

/** Words begun in a deck, read (never written) from its own ledger: one per
 * distinct word id among the scheduled card ids (`<word id>-<card>`). The slim
 * hairline under a deck row is this over the deck's real word count. */
function deckWordsBegun(id) {
  try {
    const raw = JSON.parse(localStorage.getItem(`bunki-cloze:${id}`) || 'null');
    const ids = raw && typeof raw.cards === 'object' && raw.cards ? Object.keys(raw.cards) : [];
    return new Set(ids.map((cardId) => cardId.replace(/-[^-]+$/, ''))).size;
  } catch {
    return 0;
  }
}

function renderDojoDecks(main) {
  const list = el('div', 'dojo-decks');
  let totalDue = 0;
  let totalFresh = 0;
  let counted = 0;
  const row = (id, title, sub, onClick, sum = null) => {
    const b = el('button', 'dojo-deck');
    b.type = 'button';
    b.dataset.deck = id;
    const name = el('span', 'dojo-deck-name');
    name.append(el('span', 'dojo-deck-t', title), el('span', 'dojo-deck-sub', sub));
    b.append(name);
    if (sum) {
      const n = el('span', 'dojo-deck-n');
      const due = el('span', 'dojo-deck-due' + (sum.due ? ' is-due' : ''));
      due.append(el('b', '', String(sum.due)), document.createTextNode(` ${tx('復習', 'due')}`));
      const fresh = el('span', 'dojo-deck-new');
      fresh.append(el('b', '', String(sum.fresh)), document.createTextNode(` ${tx('新', 'new')}`));
      n.append(due, fresh);
      b.append(n);
      if (sum.words) {
        const begun = Math.min(sum.words, deckWordsBegun(id));
        const bar = el('span', 'dojo-deck-bar');
        bar.setAttribute('aria-hidden', 'true');
        bar.style.setProperty('--begun', String(begun / sum.words));
        b.append(bar);
      }
    }
    b.addEventListener('click', onClick);
    list.append(b);
  };
  if (window.__CORRIDOR_STANDALONE__ !== true) {
    row('personal', tx('私の文脈', 'My contexts'), tx('自分の段落・会話・つながり', 'personal paragraphs · conversations · connections'), () => {
      openPersonalCollection();
    });
  }
  for (const d of DOJO_DECKS) {
    const sum = learnDeckSummary(d.id);
    if (sum) {
      totalDue += sum.due;
      totalFresh += sum.fresh;
      counted += 1;
    }
    const sub = sum?.words
      ? tx(`${sum.words.toLocaleString('ja-JP')} 語`, `${sum.words.toLocaleString('en-US')} words`)
      : tx('復習と新しい文', d.en);
    row(d.id, tx(d.ja, d.en), sub, () => openDeck(d.id), sum);
  }
  row('context', tx('文脈札', 'Context cards'), tx('一語ごとの段落カード', 'one paragraph per word'), () => {
    keepScroll();
    S.view = 'contextdeck';
    render();
    window.scrollTo(0, 0);
  });
  const forecast = srsForecast();
  row('mine', tx('覚えるの札', 'My saved cards'), tx(`覚えた語 ・ ${forecast.today + forecast.fresh} 枚 待っている`, `words you saved · ${forecast.today + forecast.fresh} waiting`), () => startReview());
  for (const name of Object.keys(S.lists || {})) {
    const items = S.lists[name];
    if (!items.length) continue;
    const keys = new Set(items.map((x) => srsKey(x.t, x.id)));
    const waiting = srsDueItems().filter((i) => keys.has(srsKey(i.t, i.id))).length;
    row(`list:${name}`, name, tx(`リスト ・ ${items.length} 語 ・ ${waiting} 枚 待っている`, `list · ${items.length} words · ${waiting} waiting`), () => startReview(items));
  }
  main.append(learnHead('02', 'デッキ', 'Decks', counted ? tx(`復習 ${totalDue} · 新 ${totalFresh}`, `${totalDue} due · ${totalFresh} new`) : ''));
  main.append(list);
}

function renderDeckPlay(main) {
  if (deckPlayerError) {
    main.append(el('p', 'card-kind', tx('デッキを開けませんでした。', 'The deck could not be opened.')));
    return;
  }
  if (!deckPlayer) {
    main.append(el('p', 'card-kind', tx('読み込み中…', 'loading…')));
    loadDeckPlayer().then(
      () => S.view === 'deckplay' && render(),
      () => S.view === 'deckplay' && render(),
    );
    return;
  }
  deckPlayer
    .render(main, {
      deckId: S.deckPlay || DOJO_DECKS[0].id,
      english: bi(),
      storage: localStorage, host: deckHost(),
      onLeave() {
        delete deckSummaries[S.deckPlay];
        S.view = 'dojo';
        render();
        window.scrollTo(0, 0);
      },
    })
    .catch((err) => {
      console.error(err);
      deckPlayerError = true;
      if (S.view === 'deckplay') render();
    });
}

/** 学ぶ — the Learn room: the stage, then the numbered blocks (renderStudyHall). */
function renderFocus(main) {
  const doors = studyHallDoors();
  renderLearnStage(main, doors);
  renderStudyHall(main, doors);
}

/** 03 · the focus sitting: choose a length and what to drill, then begin. */
function renderFocusSitting(focus) {
  const forecast = srsForecast();
  const due = forecast.today + forecast.fresh;
  S.focusMin = S.focusMin || 20;
  focus.append(learnHead('03', '集中の座', 'Focus sitting', tx(`${S.focusMin} 分`, `${S.focusMin} min`)));
  focus.append(
    el(
      'p',
      'learn-gloss',
      tx(
        '時間を決めて、静かに札と向き合う。時間が来たら、そっと終わる。',
        'Set a length and sit with the cards. When the time is up, the block ends on its own.',
      ),
    ),
  );
  const pick = el('div', 'learn-focus-pick');
  pick.append(el('p', 'learn-label', tx('時間', 'how long')));
  const mins = el('div', 'focus-choices');
  for (const m of FOCUS_MINUTES) {
    const b = el('button', 'focus-chip' + (S.focusMin === m ? ' on' : ''));
    b.type = 'button';
    // the chosen length and mode are STATE, not only a class (PR #77 007479d0)
    b.setAttribute('aria-pressed', String(S.focusMin === m));
    b.append(el('span', 'focus-chip-n', String(m)));
    b.append(el('span', 'focus-chip-u', tx('分', 'min')));
    b.addEventListener('click', () => {
      S.focusMin = m;
      render();
    });
    mins.append(b);
  }
  pick.append(mins);
  focus.append(pick);

  focus.append(el('p', 'learn-label', tx('何を', 'what to drill')));
  const modes = el('div', 'focus-modes');
  const modeDefs = [
    // the sub tells the whole truth (POL-12): the block reviews each waiting
    // card once; when the clock outlasts the pool, further laps are practice
    ['due', '覚えるの札', 'your due cards', tx(`${due} 枚 待っている ・ 二周目からは稽古`, `${due} waiting · after the first lap, practice`)],
    ['kanji', '漢字だけ', 'kanji only', tx('やさしい順に', 'easiest first')],
    ['yomi', '読み探査', 'yomi probe', tx('まだ取っていない熟語を測る', 'sound out compounds you never took')],
  ];
  S.focusMode = S.focusMode || 'due';
  for (const [id, ja, en, sub] of modeDefs) {
    const b = el('button', 'focus-mode' + (S.focusMode === id ? ' on' : ''));
    b.type = 'button';
    b.setAttribute('aria-pressed', String(S.focusMode === id));
    b.append(el('span', 'focus-mode-t', tx(ja, en)));
    b.append(el('span', 'focus-mode-sub', sub));
    b.addEventListener('click', () => {
      S.focusMode = id;
      render();
    });
    modes.append(b);
  }
  focus.append(modes);

  if (S.focusEmpty) {
    focus.append(
      el(
        'div',
        'sem-empty',
        S.focusEmpty === 'due'
          ? tx('いま待っている札がない。覚えるリストに足すか、漢字だけで始めよう。', 'No cards are waiting. Add some to your list, or start a kanji-only run.')
          : S.focusEmpty === 'yomi'
            ? tx('探査できる熟語が見つからない。', 'No compounds left to probe.')
            : tx('漢字が見つからない。', 'No kanji to drill yet.'),
      ),
    );
  }

  const start = biLabel('button', 'take focus-start', `${S.focusMin}分 座る`, `sit for ${S.focusMin} minutes`);
  start.type = 'button';
  start.addEventListener('click', () => startFocus(S.focusMin, S.focusMode));
  focus.append(start);
}

/* ------------------------------------------------------------- 読み探査
 * The yomi probe: measure what was never captured. Compounds the learner
 * has NOT taken are sampled stratified across Kanken band × reading type ×
 * head kanji, shown bare (sentence context from the shelf when it has one),
 * and self-graded on one question only — could you read it. A probe is an
 * observation, never a grade: rows land in the obslog, FSRS state is never
 * written. A miss mints the word into 覚える (subject to the same daily
 * cap as any capture); a hit costs nothing. Everything here runs offline
 * from the committed data: dict core + KANJIDIC2 readings + kanken table. */

/** Katakana on-readings and dotted kun-readings become matchable variants:
 * the plain form, the rendaku'd form (first mora voiced), and the sokuon
 * form (final つ/ち/く/き → っ) — enough to recognize 学+校 = がっこう and
 * 人+人 = ひとびと without pretending to be a full morphophonology. */
const YOMI_DAKUTEN = {
  か: 'が', き: 'ぎ', く: 'ぐ', け: 'げ', こ: 'ご',
  さ: 'ざ', し: 'じ', す: 'ず', せ: 'ぜ', そ: 'ぞ',
  た: 'だ', ち: 'ぢ', つ: 'づ', て: 'で', と: 'ど',
  は: 'ば', ひ: 'び', ふ: 'ぶ', へ: 'べ', ほ: 'ぼ',
};
const YOMI_HANDAKU = { は: 'ぱ', ひ: 'ぴ', ふ: 'ぷ', へ: 'ぺ', ほ: 'ぽ' };
const yomiVariantCache = new Map();
function yomiVariantsOf(ch) {
  if (yomiVariantCache.has(ch)) return yomiVariantCache.get(ch);
  const k = D.kanji?.[ch];
  const out = [];
  const add = (reading, type) => {
    const base = kataToHira(reading).replace(/-/g, '');
    if (!base) return;
    const seen = new Set();
    const sokuon = base.length >= 2 && 'つちくき'.includes(base.at(-1)) ? base.slice(0, -1) + 'っ' : null;
    for (const v of sokuon ? [base, sokuon] : [base]) {
      for (const head of [v[0], YOMI_DAKUTEN[v[0]], YOMI_HANDAKU[v[0]]]) {
        if (!head) continue;
        const form = head + v.slice(1);
        if (!seen.has(form)) {
          seen.add(form);
          out.push([form, type]);
        }
      }
    }
  };
  for (const on of k?.on || []) add(on, 'on');
  for (const kun of k?.kun || []) {
    add(kun.split('.')[0], 'kun'); // the stem alone (compound position)
    if (kun.includes('.')) add(kun.replace('.', ''), 'kun'); // stem + okurigana
  }
  out.sort((a, b) => b[0].length - a[0].length); // greedy: longest first
  yomiVariantCache.set(ch, out);
  return out;
}

/** Classify how a compound is read against its kanji's own readings:
 * 音 (all on), 訓 (all kun), 混 (湯桶/重箱 mixes), 熟 (no per-kanji parse —
 * jukujikun, gikun, or readings beyond the variant model). Honest about
 * its limits: 熟 means "not resolvable here", never a claim about origin. */
function yomiReadingType(word, reading) {
  const target = kataToHira(reading || '');
  if (!target) return '熟';
  const chars = [...word];
  const step = (ci, rest, sawOn, sawKun) => {
    if (ci === chars.length) return rest === '' ? { sawOn, sawKun } : null;
    const ch = chars[ci];
    if (!/[一-鿿々]/.test(ch)) {
      const lit = kataToHira(ch);
      return rest.startsWith(lit) ? step(ci + 1, rest.slice(lit.length), sawOn, sawKun) : null;
    }
    const source = ch === '々' ? chars[ci - 1] : ch;
    for (const [form, type] of source ? yomiVariantsOf(source) : []) {
      if (!rest.startsWith(form)) continue;
      const hit = step(ci + 1, rest.slice(form.length), sawOn || type === 'on', sawKun || type === 'kun');
      if (hit) return hit;
    }
    return null;
  };
  const parsed = step(0, target, false, false);
  if (!parsed) return '熟';
  if (parsed.sawOn && parsed.sawKun) return '混';
  return parsed.sawOn ? '音' : '訓';
}

/** The probe pool: every core-dictionary compound (2+ kanji) the learner has
 * neither taken nor probed, carrying its hardest kanji's Kanken band and its
 * reading type. Built once per session, on first use. */
function buildYomiPool() {
  const takenWords = new Set(S.taken.filter((i) => i.t === 'word').map((i) => i.id));
  const probed = new Set(
    (S.obslog || []).filter((r) => r[1] === 'probe').map((r) => String(r[2]).slice('word:'.length)),
  );
  const pool = [];
  for (const [w, rec] of Object.entries(D.dict)) {
    if (takenWords.has(w) || probed.has(w) || !rec.r || !rec.m?.length) continue;
    const marks = [...w].filter((c) => /[一-鿿々]/.test(c));
    if (marks.length < 2) continue; // 熟語 — compounds are the probe's subject
    let kr = 0;
    let band = null;
    for (const c of new Set(marks.filter((c) => c !== '々'))) {
      const kb = D.kanken?.[c];
      if (!kb) {
        band = null;
        break;
      }
      if (kb.kr > kr) {
        kr = kb.kr;
        band = kb.kk;
      }
    }
    if (!band) continue; // no honest band — leave it out rather than guess
    pool.push({ w, r: rec.r, m: rec.m, band, kr, rt: yomiReadingType(w, rec.r), head: marks[0] });
  }
  return pool;
}

/** One stratified batch: bands round-robin (hardest first), reading types
 * cycled within each band, no head kanji repeated within the batch. */
function drawYomiBatch(pool, drawn, n = FOCUS_BATCH) {
  const byBand = new Map();
  for (const it of pool) {
    if (drawn.has(it.w)) continue;
    if (!byBand.has(it.band)) byBand.set(it.band, { kr: it.kr, cell: [] });
    byBand.get(it.band).cell.push(it);
  }
  const bands = [...byBand.entries()].sort((a, b) => b[1].kr - a[1].kr).map(([name]) => name);
  const usedHeads = new Set();
  const rtCycle = ['音', '訓', '混', '熟'];
  const out = [];
  let rtIx = 0;
  while (out.length < n && bands.length) {
    let advanced = false;
    for (const band of [...bands]) {
      if (out.length >= n) break;
      const cell = byBand.get(band).cell;
      let pick = -1;
      for (let pass = 0; pass < rtCycle.length && pick < 0; pass++) {
        const rt = rtCycle[(rtIx + pass) % rtCycle.length];
        const fits = cell.map((it, ix) => ({ it, ix })).filter(({ it }) => it.rt === rt && !usedHeads.has(it.head));
        if (fits.length) pick = fits[Math.floor(Math.random() * fits.length)].ix;
      }
      if (pick < 0) {
        const fits = cell.map((it, ix) => ({ it, ix })).filter(({ it }) => !usedHeads.has(it.head));
        if (fits.length) pick = fits[Math.floor(Math.random() * fits.length)].ix;
      }
      if (pick < 0 && cell.length) pick = Math.floor(Math.random() * cell.length);
      if (pick >= 0) {
        const it = cell.splice(pick, 1)[0];
        usedHeads.add(it.head);
        drawn.add(it.w);
        out.push(it);
        rtIx += 1;
        advanced = true;
      }
      if (!cell.length) bands.splice(bands.indexOf(band), 1);
    }
    if (!advanced) break;
  }
  return out;
}

const YOMI_RT_LABEL = { 音: ['音読み', 'on'], 訓: ['訓読み', 'kun'], 混: ['混読', 'mixed'], 熟: ['熟字訓など', 'irregular'] };

/* An instrument handle for the verification suites (the __KAIRO_* idiom):
 * read-only access to the probe's classifier and sampler, so acceptance
 * checks exercise the real code instead of a re-implementation. */
window.__KAIRO_PROBE__ = Object.freeze({
  readingType: (w, r) => yomiReadingType(w, r),
  poolStats: () => {
    const pool = buildYomiPool();
    const bands = {};
    const rts = {};
    for (const it of pool) {
      bands[it.band] = (bands[it.band] || 0) + 1;
      rts[it.rt] = (rts[it.rt] || 0) + 1;
    }
    return { n: pool.length, bands, rts };
  },
  drawStats: (n = FOCUS_BATCH) => {
    const batch = drawYomiBatch(buildYomiPool(), new Set(), n);
    return {
      n: batch.length,
      heads: new Set(batch.map((b) => b.head)).size,
      bands: new Set(batch.map((b) => b.band)).size,
      words: batch.map((b) => `${b.w}:${b.band}:${b.rt}`),
    };
  },
});

function startProbe(min) {
  D.yomiPool ||= buildYomiPool();
  const drawn = new Set();
  const queue = drawYomiBatch(D.yomiPool, drawn, FOCUS_BATCH);
  if (!queue.length) {
    S.focusEmpty = 'yomi';
    render();
    return;
  }
  S.focusEmpty = null;
  S.focus = { min, mode: 'yomi', deadline: Date.now() + min * 60000, ended: false, drawn };
  S.probe = { queue, ix: 0, revealed: false, right: 0, missed: [], minted: 0 };
  S.view = 'probe';
  startFocusTicker();
  render();
}

/** The probe room: the same zen glass as 復習 — the word alone, a shelf
 * sentence when one exists, one reveal, two honest answers. */
function renderProbe(main) {
  const pr = S.probe;
  if (!pr) {
    S.view = 'dojo';
    return renderFocus(main);
  }
  // the clock keeps the queue full; once it ends the batch in hand plays out
  if (pr.ix >= pr.queue.length && S.focus && !S.focus.ended && Date.now() < S.focus.deadline) {
    const more = drawYomiBatch(D.yomiPool || [], S.focus.drawn, FOCUS_BATCH);
    if (more.length) pr.queue.push(...more);
  }
  if (pr.ix >= pr.queue.length) {
    main.append(withEn(el('p', 'eyebrow', '読み探査'), 'yomi probe', 'en-inline'));
    const n = pr.right + pr.missed.length;
    main.append(el('h1', 'view-title', tx(`探査おわり — ${n} 語`, `Probe done — ${n} word${n === 1 ? '' : 's'}`)));
    const sum = el('div', 'review-summary');
    sum.append(el('span', 'pool-tag', tx(`読めた ${pr.right}`, `read ${pr.right}`)));
    sum.append(el('span', 'pool-tag', tx(`読めなかった ${pr.missed.length}`, `missed ${pr.missed.length}`)));
    main.append(sum);
    if (pr.missed.length) {
      main.append(
        el(
          'p',
          'gloss',
          tx(
            `落ちた ${pr.minted} 語は札になって、明日からの新しい札に混ざる。`,
            `The ${pr.minted} misses became cards — they join the daily stream of new ones.`,
          ),
        ),
      );
      for (const it of pr.missed) {
        const row = el('div', 'leech-row');
        row.append(el('span', 'w', `${it.w}（${it.r}）`));
        const door = biLabel('button', 'chip', 'ページへ', 'full entry');
        door.type = 'button';
        door.addEventListener('click', () => go({ t: 'word', id: it.w }));
        row.append(door);
        main.append(row);
      }
    }
    const out = biLabel('button', 'take', '道場へ', 'back to the dojo');
    out.type = 'button';
    out.addEventListener('click', () => {
      endFocus();
      S.probe = null;
      S.view = 'dojo';
      render();
    });
    main.append(out);
    return;
  }
  const it = pr.queue[pr.ix];
  const progress = el('div', 'zen-progress');
  const fill = el('i');
  fill.style.width = `${Math.min(100, Math.round((pr.ix / pr.queue.length) * 100))}%`;
  progress.append(fill);
  main.append(progress);

  const face = el('div', 'review-face');
  face.append(el('div', 'review-front', it.w));
  const context = findExamples(it.w, 1)[0];
  if (context) {
    const line = el('p', 'probe-context');
    // full ladder on the neighbours; the probed word itself stays sealed —
    // its reading is the question, and afterward it lives on the answer face
    renderSentenceTokens(line, context.tokens, {
      targetId: it.w,
      contextId: context.passage || 'bank',
    });
    if (pr.revealed) line.append(sentenceDoor(context, it.w));
    face.append(line);
  } else if (!D.exampleBank?.has(it.w) && window.__CORRIDOR_STANDALONE__ !== true) {
    ensureBankExamples(it.w).then((entries) => {
      if (entries.length && S.view === 'probe' && S.probe?.queue[S.probe.ix] === it && !S.probe.revealed) render();
    });
  }
  if (pr.revealed) {
    face.append(el('div', 'review-reading', it.r));
    face.append(el('div', 'review-sense', it.m.slice(0, 3).join('; ')));
    const rt = YOMI_RT_LABEL[it.rt] || YOMI_RT_LABEL['熟'];
    face.append(el('div', 'probe-meta', `${tx(`漢検${it.band}`, `Kanji Kentei ${kankenGradeLabel(it.band)}`)} · ${tx(rt[0], rt[1])}`));
  }
  main.append(face);

  if (!pr.revealed) {
    face.addEventListener('click', () => {
      if (pr.pending || S.probe !== pr || pr.queue[pr.ix] !== it) return;
      pr.revealed = true;
      render();
    });
    const btn = biLabel('button', 'take review-reveal', '読みを見る', 'show the reading');
    btn.type = 'button';
    btn.id = 'probe-reveal';
    btn.disabled = !!pr.pending;
    btn.addEventListener('click', () => {
      if (pr.pending || S.probe !== pr || pr.queue[pr.ix] !== it) return;
      pr.revealed = true;
      render();
    });
    main.append(btn);
    return;
  }
  const row = el('div', 'grade-row probe-row');
  const answers = [
    ['again', '読めなかった', 'missed it', false],
    ['good', '読めた', 'read it', true],
  ];
  for (const [tone, ja, en, ok] of answers) {
    const b = el('button', `grade g-${tone}`);
    b.type = 'button';
    b.dataset.probe = ok ? 'right' : 'wrong';
    b.disabled = !!pr.pending;
    b.append(el('span', 'g-label', tx(ja, en)));
    b.addEventListener('click', async () => {
      if (pr.pending || S.probe !== pr || pr.queue[pr.ix] !== it || !pr.revealed || !recordWritable()) return;
      const epoch = recordEpoch;
      const ix = pr.ix;
      const pending = {};
      const now = Date.now();
      const key = srsKey('word', it.w);
      let minted = 0;
      pr.pending = pending;
      try {
        if (S.view === 'probe') render();
        const saved = await commitStorePatch((latest) => {
          if (S.probe !== pr || pr.ix !== ix || pr.queue[ix] !== it) throw new Error('Probe changed before its save');
      const patch = {};
      if (!ok && !latest.taken.some((t) => t.t === 'word' && t.id === it.w)) {
        patch.taken = [
          ...latest.taken,
          {
            t: 'word',
            id: it.w,
            label: it.w,
            kind: NODE_KIND.word[0],
            kindEn: NODE_KIND.word[1],
            from: null,
            ts: now,
            // the learner's own 読めなかった is the choice that mints this
            // card — the probe told them so before they pressed it
            started: now,
          },
        ];
        minted = 1;
      }
      // the probe is an observation: one obslog row, zero FSRS writes. The
      // mint and its evidence land as ONE commit — a minted card must not
      // wait on the tap debounce, and a failed persist mints nothing
      patch.obslog = [...(latest.obslog || []), [now, 'probe', key, ok ? 3 : 1, minted]];
      return patch;
        });
      if (!saved || !recordReady(epoch) || S.probe !== pr || pr.ix !== ix || pr.queue[ix] !== it) return;
      if (minted) pr.minted += 1;
      if (ok) pr.right += 1;
      else pr.missed.push(it);
      pr.ix += 1;
      pr.revealed = false;
      } finally {
        if (pr.pending === pending) pr.pending = null;
        if (recordReady(epoch) && S.probe === pr && S.view === 'probe') render();
      }
    });
    row.append(b);
  }
  main.append(row);
}

function renderSchedule(container) {
  const preview = schedulePreview();
  container.append(
      // the scheduler is named for the learner; its internal parameter-set
      // slug (bunki-fsrs6-…) is provenance and stays in exports/debug —
      // it leaked into every entry footer (P2, full-instrument review).
      // When the learner's own fitted weights rule (R3-D), the footer says
      // so: the schedule shown is never passed off as the default's.
      el(
        'p',
        'card-kind',
        tx('予定される復習', 'if you reviewed this now') +
          ' — FSRS-6' +
          (srsCustom ? tx('・自分の記録で調整済み', ' · tuned from your record') : ''),
      ),
  );
  if (!preview) {
    container.append(el('div', 'sem-empty', tx('スケジューラを読み込めなかった。', 'The scheduler failed to load.')));
    return;
  }
  const table = el('table', 'sched');
  const head = el('tr');
  const headers = [
    ['評価', 'your rating'],
    ['つぎ', 'next review'],
    ['日時', 'due'],
    ['安定度', 'stability'],
  ];
  for (const [ja, en] of headers) head.append(withEn(el('th', null, ja), en));
  table.append(head);
  const labels = {
    again: ['もう一度', 'again'],
    hard: ['難しい', 'hard'],
    good: ['ふつう', 'good'],
    easy: ['簡単', 'easy'],
  };
  for (const key of ['again', 'hard', 'good', 'easy']) {
    const row = el('tr');
    row.append(withEn(el('td', null, labels[key][0]), labels[key][1]));
    row.append(el('td', key === 'good' ? 'good' : null, preview[key].when));
    row.append(el('td', null, preview[key].due));
    row.append(el('td', null, preview[key].stability.toFixed(2)));
    table.append(row);
  }
  container.append(table);
  const note = el('div', 'note');
  note.textContent = tx('実計算のプレビュー。まだ何も保存されない。', 'A real FSRS-6 preview — nothing is saved yet.');
  container.append(note);
}

/* 学習の記録 — one quiet fold at the foot of every entry (operator,
 * 2026-08-27): collapsed it is a single line saying how far this card has
 * come; open it holds the real history (adds, reviews, lapses, stability,
 * encounters from the observation ledger), then the FSRS-6 preview table,
 * then — when a context sentence exists — the card-variant preview. Only
 * what is actually recorded is shown; nothing is invented. */
function renderStudyFold(sheet, node, variantTarget) {
  if (personalHost) return;
  const key = srsKey(node.t, node.id);
  const open = S.studyOpen === key;
  const srs = S.srs[key];
  const wrap = el('div', 'study-fold');
  const head = el('button', open ? 'fold-head open' : 'fold-head');
  head.type = 'button';
  head.setAttribute('aria-expanded', String(open));
  head.append(el('span', 'fold-title', tx('学習の記録', 'study progress')));
  head.append(
    el(
      'span',
      'fold-sub',
      srs
        ? tx(`復習 ${srs.reps || 0} 回`, `${srs.reps || 0} review${(srs.reps || 0) === 1 ? '' : 's'}`)
        : tx('まだ記録なし', 'no history yet'),
    ),
  );
  head.append(el('span', 'fold-arrow', open ? '▾' : '▸'));
  head.addEventListener('click', () => {
    S.studyOpen = open ? null : key;
    render();
  });
  wrap.append(head);
  if (!open) {
    sheet.append(wrap);
    return;
  }
  const body = el('div', 'fold-body');
  const item = S.taken.find((t) => t.t === node.t && t.id === node.id);
  const facts = [];
  if (item && finiteNumber(item.ts)) {
    facts.push(tx(`追加 — ${dayKey(new Date(item.ts))}`, `added ${dayKey(new Date(item.ts))}`));
  }
  if (srs) {
    facts.push(
      tx(`復習 ${srs.reps || 0} 回 ・ もう一度 ${srs.lapses || 0} 回`, `${srs.reps || 0} reviews · ${srs.lapses || 0} lapses`),
    );
    if (finiteNumber(srs.stability)) {
      facts.push(tx(`安定度 ${Number(srs.stability).toFixed(2)}`, `stability ${Number(srs.stability).toFixed(2)}`));
    }
    const due = srs.due ? new Date(srs.due) : null;
    if (due && !Number.isNaN(due.getTime())) {
      facts.push(tx(`つぎ — ${dayKey(due)}`, `next due ${dayKey(due)}`));
    }
  }
  const enc = (S.obslog || []).filter((r) => r[2] === key);
  if (enc.length) {
    const kinds = { drift: 0, dojo: 0, probe: 0 };
    for (const r of enc) if (r[1] in kinds) kinds[r[1]] += 1;
    const parts = [];
    if (kinds.drift) parts.push(tx(`墨流し ${kinds.drift}`, `drift ${kinds.drift}`));
    if (kinds.dojo) parts.push(tx(`道場 ${kinds.dojo}`, `dojo ${kinds.dojo}`));
    if (kinds.probe) parts.push(tx(`読みチェック ${kinds.probe}`, `reading checks ${kinds.probe}`));
    if (parts.length) facts.push(tx('出会い — ', 'met in — ') + parts.join(' ・ '));
  }
  if (!facts.length) {
    facts.push(tx('まだ記録なし — 覚えて、復習が始まると育つ。', 'No history yet — it grows once this card is memorized and reviewed.'));
  }
  for (const f of facts) body.append(el('p', 'study-fact', f));
  renderSchedule(body);
  if (variantTarget) renderCardVariant(body, variantTarget);
  wrap.append(body);
  sheet.append(wrap);
}

/** Variant A (#38): the SAME target word rendered both ways. */
function renderCardVariant(container, target) {
  const source = target.from ? D.passages.find((p) => p.id === target.from.passage) : null;
  let sentence = null;
  let sentenceTokens = null;
  if (source && !source.tokens) ensureArticle(source).then(() => render()).catch(() => {});
  if (source?.tokens) {
    const tokens = source.tokens;
    let start = target.from.index;
    let end = target.from.index;
    while (start > 0 && !'。！？'.includes(tokens[start - 1].s)) start -= 1;
    while (end < tokens.length - 1 && !'。！？'.includes(tokens[end].s)) end += 1;
    sentenceTokens = tokens.slice(start, end + 1);
    sentence = sentenceTokens.map((t) => t.s).join('');
  }

  const box = el('div', 'card-preview');
  const kind = S.variants.cards;
  // An MCD card without a context sentence cannot exist — and SAYING so on
  // every dictionary-opened word read as a broken feature, not a comparison
  // (operator, 2026-08-27). No context: the MCD preview simply stays away
  // (it appears by itself once the source article's tokens arrive).
  if (kind === 'mcd' && !sentenceTokens) return;
  box.append(
    el(
      'p',
      'card-kind',
      kind === 'mcd'
        ? tx('MCD — 文脈まるごと、一語だけ空ける', 'MCD card — the whole context, one word blanked')
        : tx('単語札 — 表は語だけ（Animecards）', 'Word card — the front is the word alone (Animecards)'),
    ),
  );
  const face = el('div', 'card-face');

  if (kind === 'mcd') {
    for (const token of sentenceTokens) {
      if (token.b === target.id && token.c) {
        face.append(el('span', 'cloze', '　　'));
      } else {
        face.append(document.createTextNode(token.s));
      }
    }
  } else {
    face.append(el('span', 'target', target.id));
  }
  box.append(face);

  const back = el('div', 'card-back');
  const word = D.words[target.id];
  const reading = word?.r || '';
  const gloss = word?.g || '';
  if (kind === 'mcd') {
    back.textContent = `${target.id}${reading ? `（${reading}）` : ''}${gloss ? ` — ${gloss}` : ''}`;
  } else {
    back.textContent =
      `${reading}${gloss ? ` — ${gloss}` : ''}` + (sentence ? `\n${sentence}` : '');
    back.style.whiteSpace = 'pre-line';
  }
  box.append(back);

  container.append(box);
}

/** Real usages from the committed shelf: sentences containing the word. */
function findExamples(id, cap = 4) {
  const out = [];
  for (const p of D.passages) {
    if (!p.tokens) continue; // not yet fetched — prefetch fills these in
    let sentence = [];
    let start = 0;
    let hit = false;
    for (const [index, t] of p.tokens.entries()) {
      sentence.push(t);
      if (t.c && t.b === id) hit = true;
      if ('。！？'.includes(t.s)) {
        if (hit) out.push({ tokens: sentence, source: learnerSourceLabel(p), passage: p.id, start });
        sentence = [];
        start = index + 1;
        hit = false;
        if (out.length >= cap) return out;
      }
    }
    if (hit && sentence.length) out.push({ tokens: sentence, source: learnerSourceLabel(p), passage: p.id, start });
    if (out.length >= cap) return out;
  }
  // the bank fills what the shelf cannot — already-fetched sentences only
  // (ensureBankExamples warms this cache; callers refresh once it lands)
  const banked = D.exampleBank?.get(id);
  if (banked) {
    const seen = new Set(out.map((ex) => ex.tokens.map((t) => t.s).join('')));
    for (const ex of banked) {
      if (out.length >= cap) break;
      const text = ex.tokens.map((t) => t.s).join('');
      if (!seen.has(text)) {
        seen.add(text);
        out.push(ex);
      }
    }
  }
  return out;
}

/** Resolve an exact sentence occurrence. Repeated identical sentences need
 * their retained start; an ambiguous text match never invents a position. */
function sentenceSource(tokens, passageId, startHint) {
  const p = D.passages.find((entry) => entry.id === passageId);
  if (!tokens?.length || !p?.tokens?.length) return null;
  const matches = (start) => start >= 0 && start + tokens.length <= p.tokens.length &&
    tokens.every((token, offset) => token.s === p.tokens[start + offset].s && token.b === p.tokens[start + offset].b);
  if (Number.isInteger(startHint)) return matches(startHint) ? { passage: passageId, index: startHint } : null;
  let found = -1;
  for (let start = 0; start <= p.tokens.length - tokens.length; start += 1) {
    if (!matches(start)) continue;
    if (found !== -1) return null;
    found = start;
  }
  return found === -1 ? null : { passage: passageId, index: found };
}

/* ------------------------------------------------- 用例の蔵 (example bank)
 * SNOW T15/T23 sentences (CC BY 4.0), tokenised at build time into the
 * corridor's own token grammar and sharded for lazy fetch: a word's index
 * shard names its sentence ids; sentence shards carry [tokens, english].
 * Served build only — the single file keeps shelf sentences and stays
 * honest about the rest. See tools/build_examples.py. */
const EXAMPLE_DIR = 'data/proprietary_safe/examples';
function exampleFnv(word) {
  let h = 0x811c9dc5;
  const bytes = new TextEncoder().encode(word);
  for (const b of bytes) {
    h ^= b;
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h & 15;
}
function inflateExampleToken(row) {
  const [s, b, r, c, p, f] = row;
  return { s, b, r, c: !!c, p, f: (f || []).map((pair) => (pair[1] ? { t: pair[0], r: pair[1] } : { t: pair[0] })) };
}
async function fetchExampleJson(path) {
  const res = await fetch(`${EXAMPLE_DIR}/${path}`);
  if (!res.ok) throw new Error(`${path} → ${res.status}`);
  return res.json();
}
async function ensureBankExamples(word) {
  if (window.__CORRIDOR_STANDALONE__ === true) return [];
  D.exampleBank ||= new Map();
  if (D.exampleBank.has(word)) return D.exampleBank.get(word);
  D.examplePending ||= new Map();
  if (D.examplePending.has(word)) return D.examplePending.get(word);
  const job = (async () => {
    try {
      D.exampleManifest ||= await fetchExampleJson('manifest.json');
      D.exampleIndexShards ||= new Map();
      const ix = exampleFnv(word);
      if (!D.exampleIndexShards.has(ix)) {
        D.exampleIndexShards.set(ix, await fetchExampleJson(`ex-${String(ix).padStart(2, '0')}.json`));
      }
      const sids = D.exampleIndexShards.get(ix)[word] || [];
      const per = D.exampleManifest.sharding.sentsPerShard;
      D.exampleSentShards ||= new Map();
      const entries = [];
      for (const sid of sids) {
        const shard = Math.floor(sid / per);
        if (!D.exampleSentShards.has(shard)) {
          D.exampleSentShards.set(shard, await fetchExampleJson(`s-${String(shard).padStart(2, '0')}.json`));
        }
        const row = D.exampleSentShards.get(shard)[sid - shard * per];
        if (row) {
          const src = D.exampleManifest.sources?.[row[2]] || null;
          entries.push({
            tokens: row[0].map(inflateExampleToken),
            en: row[1] || '',
            source: src ? tx(src.labelJa, src.labelEn) : tx('用例', 'examples corpus'),
            bank: true,
          });
        }
      }
      D.exampleBank.set(word, entries);
      return entries;
    } catch {
      D.exampleBank.set(word, []); // absence recorded — never retried this session
      return [];
    } finally {
      D.examplePending.delete(word);
    }
  })();
  D.examplePending.set(word, job);
  return job;
}

/* ---------------------------------- the reader's grammar, outside the reader
 * Any sentence the app shows — a sheet's 用例, a review cloze, a probe's
 * context line — carries the reader's click grammar, and starts BARE:
 * no furigana until it is asked for (operator's law, 2026-08-12 — the
 * sentence is the exercise; readings on request only, whatever the
 * reader's own dial says). One tap opens the word's popup, as in the
 * reader (reader lane 2026-10-02): the reading and the meaning at once,
 * Save, and Full entry ›. Taps land in the obslog. */
function renderSentenceTokens(container, tokens, opts = {}) {
  const target = opts.targetId || null;
  const contextId = opts.contextId || 'sentence';
  const source = sentenceSource(tokens, contextId, opts.start);
  tokens.forEach((token, index) => {
    if (!token.c || !token.f?.length) {
      // 禁則処理 — a line must never open with a closing mark. WebKit
      // breaks between an atomic token box (the inline-flex word button)
      // and the text run after it, so a bare 、 could start a line
      // (operator's real-phone screenshot, 2026-08-20). A mark that is
      // nothing but clinging punctuation is glued to the box it follows
      // inside one no-break span; ordinary text keeps native flow, where
      // the browser's own kinsoku already holds.
      const textNode = document.createTextNode(token.s);
      const prev = container.lastChild;
      if (prev && prev.nodeType === 1 && /^[、。，．！？」』）〉》〕］｝ー〜…‥・]+$/.test(token.s)) {
        const glue = el('span', 'kinsoku-glue');
        container.replaceChild(glue, prev);
        glue.append(prev, textNode);
        return;
      }
      container.append(textNode);
      return;
    }
    const isTarget = target && token.b === target;
    if (isTarget && opts.hideTarget) {
      container.append(document.createTextNode('＿＿＿'));
      return;
    }
    if (isTarget && !opts.targetLive) {
      // the asked/answered word stands bare and sealed — its reading lives
      // on the answer face, never one accidental tap away
      container.append(el('span', 'example-hit', token.s));
      return;
    }
    // A sentence outside the reader is still a sentence: 用例, the 文 page and
    // the review answer face all ride this ladder, and all three were
    // pointer-only spans — no tab stop, no name, nothing a screen reader
    // could reach, while the reader's own tokens are labelled buttons
    // (E3 round-A, dead-ends lens; CONFIRMED on the head). Same element,
    // same grammar.
    const span = el(
      'button',
      'tok content sentence-tok' + (isTarget ? ' example-hit' : ''),
    );
    span.type = 'button';
    span.setAttribute('aria-haspopup', 'dialog');
    span.setAttribute(
      'aria-label',
      tx(`${token.s} · 語 · 押すと読みと意味`, `${token.s} · word · activate for the reading and meaning`),
    );
    span.append(wordRow(displayPairs(token), { furigana: 0, revealed: false }));
    // the reader's grammar (reader lane 2026-10-02): one tap opens the word's popup — reading and meaning
    // at once, Save, and Full entry ›, which opens the entry with this sentence as its provenance
    const from = source ? { passage: source.passage, index: source.index + index } : null;
    const openEntry = () => {
      removeMini();
      obsLog('tap', srsKey('word', token.b), 3, contextId);
      go({ t: 'word', id: token.b, ...(from ? { from, ctxScope: 'sent' } : {}) });
    };
    span.addEventListener('contextmenu', (ev) => ev.preventDefault());
    span.addEventListener('click', (ev) => {
      ev.stopPropagation();
      if (ev.detail !== 0 && Date.now() < swallowClickUntil) return;
      // a press on the word whose popup is open put it away; its click does not open it again
      if (ev.detail !== 0 && miniClosedOnAnchor === span) { miniClosedOnAnchor = null; return; }
      obsLog('tap', srsKey('word', token.b), 2, contextId);
      showMini(span, token, openEntry, { focusEntry: ev.detail === 0, from });
    });
    container.append(span);
  });
}

/* ------------------------------------------------------------- AI in the app
 * Phase 3 of the operator's order: the AI lives IN the app. The app asks once
 * for an API key, stored on this device only and bound to the explicitly
 * configured provider origin. With a key present, AI doors appear;
 * without one they are quietly absent — never broken, never nagging. */
const AI_KEY_STORE = 'kairo-ai-key';
const AI_DEVICE_STORE = 'kairo-ai-provider-v1';
function aiKey() {
  return aiTransport().key;
}
const AI_TEACHING_SURFACES = new Set(['chat', 'word-tutor', 'quiz', 'cards', 'examples', 'coach']);
const AI_TEACHING_CONTEXT_LABEL = '\n\nDerived learning context (guidance only):\n';
/** Resolve only existing local forms. Imported keys and displayed learner text
 * cannot become teaching targets merely by appearing in a derived node map. */
function aiTeachingSubject(key) {
  if (typeof key !== 'string') return null;
  const cut = key.indexOf(':');
  if (cut < 1) return null;
  const kind = key.slice(0, cut), id = key.slice(cut + 1);
  const form = kind === 'word' && (owns(D.dict, id) || owns(D.words, id) || dictionaryRowsForForm(id).length > 0) ? id :
    kind === 'grammar' ? GRAMMARS().find((grammar) => grammar.id === id)?.p :
    kind === 'kanji' && (owns(D.kanji, id) || window.BunkiSkipUI?.getKanji(S.skipUi, id)) ? id : null;
  if (typeof form !== 'string' || !form.trim() || form.length > 80) return null;
  return { kind, form };
}
/** One pure query immediately before dispatch. This value grants no capture,
 * assessment, source-processing or scheduling authority. */
function aiTeachingContext() {
  if (typeof readingModule?.prepareTeachingContext !== 'function') throw new Error('learning-context-unavailable');
  const model = learnerModel();
  const targets = [], confusions = [];
  for (const item of model.frontier) {
    const subject = aiTeachingSubject(item.key), node = model.nodes[item.key];
    if (!subject || !node || targets.some((target) => target.kind === subject.kind && target.form === subject.form)) continue;
    const provenance = node.measured > 0 ? node.observed > 0 ? 'mixed' : 'measured' : node.observed > 0 ? 'observed' : null;
    if (!provenance) continue;
    targets.push({ ...subject, provenance });
    if (targets.length === 6) break;
  }
  for (const focus of model.assessments.focus) {
    if (targets.length >= 6) break;
    const subject = aiTeachingSubject(focus.subject);
    if (!subject || targets.some(target => target.kind === subject.kind && target.form === subject.form)) continue;
    targets.push({ ...subject, provenance: 'observed' });
  }
  const pairs = new Set();
  for (const edge of model.edges) {
    const first = aiTeachingSubject(edge.a), other = aiTeachingSubject(edge.b);
    if (!first || !other) continue;
    const identity = [JSON.stringify(first), JSON.stringify(other)].sort();
    if (identity[0] === identity[1] || pairs.has(JSON.stringify(identity))) continue;
    pairs.add(JSON.stringify(identity));
    confusions.push({ ...first, otherKind: other.kind, otherForm: other.form, provenance: 'observed' });
    if (confusions.length === 4) break;
  }
  return readingModule.prepareTeachingContext({ model, targets, confusions });
}
/* The provider seam belongs to device settings, never the learner record.
 * A configured path prefix is supported for Anthropic-compatible gateways;
 * credentials are bound to a canonical origin and redirects are refused. */
const AI_DEFAULT_BASE_URL = 'https://api.anthropic.com';
const AI_DEFAULT_MODEL = 'claude-opus-5';
/** One request budget, mirroring packages/ai/src/runtime.ts
 * DEFAULT_TIMEOUT_MS (controller §9): ten seconds, enforced by aborting the
 * in-flight request — never by racing a promise and walking away from a
 * live socket. A stalled request used to leave 考え中… on screen until the
 * browser gave up the socket; now it takes each caller's quiet failure line. */
const AI_TIMEOUT_MS = 10000;
function canonicalAiBaseUrl(value) {
  if (!nonEmptyString(value) || value.length > 2048 || /[\s\\]/u.test(value) ||
      Array.from(value).some((character) => character.charCodeAt(0) < 32 || character.charCodeAt(0) === 127)) return null;
  try {
    const url = new URL(value);
    if (url.protocol !== 'https:' || url.username || url.password || url.search || url.hash) return null;
    return `${url.origin}${url.pathname.replace(/\/+$/, '')}`;
  } catch {
    return null;
  }
}

/** Read one atomic settings snapshot. A damaged or mismatched configuration
 * cannot fall back to an old key. Legacy bare keys have no trusted origin:
 * even an old learner record may have imported its provider settings. Keep
 * those bytes locally, but require explicit reconnection before using them. */
function aiTransport() {
  const defaults = { baseUrl: AI_DEFAULT_BASE_URL, model: AI_DEFAULT_MODEL, origin: AI_DEFAULT_BASE_URL, key: '' };
  try {
    const raw = localStorage.getItem(AI_DEVICE_STORE);
    if (raw === null) return { ...defaults, requiresBinding: !!localStorage.getItem(AI_KEY_STORE) };
    const config = JSON.parse(raw);
    const baseUrl = plainRecord(config) && canonicalAiBaseUrl(config.baseUrl);
    if (!baseUrl || config.v !== 1 || !nonEmptyString(config.model) || config.model.length > 200) return { ...defaults, invalid: true };
    const origin = new URL(baseUrl).origin;
    if (!plainRecord(config.credential) || config.credential.origin !== origin || typeof config.credential.key !== 'string' || config.credential.key.length > 8192 ||
        ['\r', '\n', '\0'].some((character) => config.credential.key.includes(character))) {
      return { ...defaults, invalid: true };
    }
    if (config.configId !== undefined && !/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/u.test(config.configId))
      return { ...defaults, invalid: true };
    return { baseUrl, model: config.model, origin, key: config.credential.key, configId: config.configId || 'legacy-v1' };
  } catch {
    return { ...defaults, invalid: true };
  }
}

function aiProvider() {
  const { baseUrl, model } = aiTransport();
  return { baseUrl, model };
}

function saveAiDeviceConfig(baseUrl, model, key) {
  const canonical = canonicalAiBaseUrl(baseUrl);
  if (!canonical || !nonEmptyString(model) || model.length > 200 || typeof key !== 'string' || key.length > 8192 ||
      ['\r', '\n', '\0'].some((character) => key.includes(character))) return false;
  try {
    localStorage.setItem(AI_DEVICE_STORE, JSON.stringify({
      v: 1, baseUrl: canonical, model, configId: crypto.randomUUID(),
      credential: { origin: new URL(canonical).origin, key },
    }));
  } catch {
    return false;
  }
  // The atomic settings write is authoritative even if legacy cleanup fails.
  // A key removal saves an empty credential rather than reviving this fallback.
  try { localStorage.removeItem(AI_KEY_STORE); } catch { /* inert legacy bytes */ }
  revalidateTutorRequests();
  return true;
}

/* --------------------------------------------------- AIの記録 (the archive)
 * "Not a word is lost" (ledger P1): every learner message and every reply,
 * on every AI surface, lands in an append-only IndexedDB archive — beside
 * the localStorage envelope, whose quota whole transcripts would eat. The
 * archive is memory, never authority: nothing here grades, schedules, or
 * touches FSRS state. And it must never cost a conversation — a failed
 * write is swallowed and counted (the storage layer's never-block posture),
 * the call itself proceeds. Rows are
 * { surface, role: 'user'|'assistant'|'tutor'|'app', content, model, ts,
 *   contextRef? } — 'app' marks the app's own quiet failure line, 'tutor'
 * marks turns migrated from the old capped chat store, whose provenance
 * (reply or failure line) the old shape never recorded. */
const AI_LOG_DB = 'kairo-ai-log';
const AI_LOG_TURNS = 'turns';
const AI_LOG_JOURNAL = 'imports';
let aiLogDbPromise = null;
let aiLogConnection = null;
let aiLogDropped = 0;

function aiLogOpen() {
  if (!recordOwner || recordDeparted) return Promise.resolve(null);
  if (aiLogDbPromise) return aiLogDbPromise;
  aiLogDbPromise = new Promise((done) => {
    let settled = false;
    let request;
    const finish = (db) => {
      if (settled) { db?.close(); return; }
      settled = true;
      clearTimeout(timer);
      if (db) aiLogConnection = db;
      done(db);
    };
    // A blocked upgrade is not an empty archive. Late success must close its
    // handle, including after a tab has relinquished the origin-wide lock.
    const timer = setTimeout(() => finish(null), 5000);
    try {
      request = indexedDB.open(AI_LOG_DB, 3);
      request.onupgradeneeded = () => {
        if (settled || !recordOwner || recordDeparted) { request.transaction.abort(); return; }
        const db = request.result;
        if (!db.objectStoreNames.contains(AI_LOG_TURNS)) db.createObjectStore(AI_LOG_TURNS, { keyPath: 'id', autoIncrement: true });
        if (!db.objectStoreNames.contains(AI_LOG_JOURNAL)) db.createObjectStore(AI_LOG_JOURNAL, { keyPath: 'id' });
        const turns = request.transaction.objectStore(AI_LOG_TURNS);
        // Legacy rows can carry arbitrary turn.id metadata before recovery
        // wraps them. Uniqueness is checked in each serialized write TX.
        if (!turns.indexNames.contains('logical-id')) turns.createIndex('logical-id', 'turn.id');
      };
      request.onsuccess = () => {
        const db = request.result;
        if (!recordOwner || recordDeparted) { db.close(); finish(null); return; }
        db.onversionchange = () => {
          db.close(); aiLogConnection = null; recordRecovered = false; recordEpoch += 1;
          protectStore('保存形式が変わったため保存を止めた。再読み込みして続ける。',
            'The storage version changed. Saving is paused; reload to continue.');
        };
        finish(db);
      };
      request.onerror = request.onblocked = () => finish(null);
    } catch { finish(null); }
  });
  return aiLogDbPromise;
}

function canonicalRecordJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalRecordJson).join(',')}]`;
  if (plainRecord(value)) return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalRecordJson(value[key])}`).join(',')}}`;
  return JSON.stringify(value);
}
function validArchiveTurn(row) {
  return plainRecord(row) && safeJsonValue(row) && nonEmptyString(row.surface) &&
    AI_EVIDENCE_ROLES.has(row.role) && typeof row.content === 'string' &&
    Number.isSafeInteger(row.ts) && row.ts > 0 && optional(row, 'model', nonEmptyString) &&
    optional(row, 'xid', nonEmptyString) && optional(row, 'contextRef', nonEmptyString) &&
    optional(row, 'id', (id) => (Number.isSafeInteger(id) && id > 0) || nonEmptyString(id));
}
function validArchiveRows(rows) {
  if (!Array.isArray(rows) || !rows.every(validArchiveTurn)) return false;
  const keys = rows.filter((row) => owns(row, 'id')).map((row) => JSON.stringify(row.id));
  return new Set(keys).size === keys.length;
}
function storedArchiveRow(row) {
  return plainRecord(row) && row.format === 'kairo-archive-row' && row.v === 1 &&
    Number.isSafeInteger(row.id) && row.id > 0 &&
    Object.keys(row).every((key) => ['format', 'v', 'id', 'turn'].includes(key)) && validArchiveTurn(row.turn);
}
