  // 柿 焦茶 — the iro card verbatim
  iwa: {
    pal: { mode: 0, low: [0.7, 0.52, 0.38], high: [0.3, 0.16, 0.08], sheen: [0.05, 0.045, 0.04] },
    wetScale: 1.0,
    still: '#3e2410',
  },
  // 漆 胡粉 — the iro card verbatim (additive shell-white)
  rokusho: {
    pal: {
      mode: 1,
      low: [0.3, 0.28, 0.25],
      high: [0.94, 0.91, 0.85],
      sheen: [0.14, 0.13, 0.12],
      spark: [1.0, 0.98, 0.92],
      metal: 0.25,
    },
    wetScale: 0.9,
    still: '#efe9dc',
  },
  // 金 金泥 — the canon, kept no matter what
  yoru: {
    pal: {
      mode: 1,
      low: [0.42, 0.3, 0.1],
      high: [1.0, 0.83, 0.45],
      sheen: [0.1, 0.12, 0.2],
      spark: [1.0, 0.9, 0.6],
      metal: 1,
    },
    wetScale: 0.85,
    still: '#d9b25f',
  },
  // 浪 波の泡 — spindrift, TUNED against ink-hoku-nami.png (light end exact)
  nami: {
    pal: {
      mode: 1,
      low: [0.5, 0.58, 0.66],
      high: [0.9, 0.94, 0.97],
      sheen: [0.1, 0.12, 0.16],
      spark: [0.95, 1.0, 1.0],
      metal: 0.35,
    },
    wetScale: 0.9,
    still: '#eae6d8',
  },
  // 板 — canonical keyblock sumi on print cream
  keyblock: {
    pal: {
      mode: 0,
      low: [0.512, 0.448, 0.352],
      high: [0.16, 0.16, 0.24],
      sheen: [0.05, 0.055, 0.06],
    },
    wetScale: 1.0,
    still: '#26221c',
  },
  // 雷 — canonical gold carried onto 山下白雨's storm paper
  hakuu: {
    pal: {
      mode: 1,
      low: [0.42, 0.3, 0.1],
      high: [1.0, 0.83, 0.45],
      sheen: [0.1, 0.12, 0.2],
      spark: [1.0, 0.9, 0.6],
      metal: 1,
    },
    wetScale: 0.85,
    still: '#d9a93f',
  },
  // 殻 燐光 — phosphor, TUNED against ink-cyber-ghost.png (light end exact)
