/* Rooms expose their purpose independently from the existing material register.
 * Concepts use data-room; data-register retains the stage-sensitive CSS from
 * the 2026-09-24 register study — plus the attempt's stage
 * (--stage), whether an answer exists (data-answered), and the shelf's three grades of door. */
const ROOM_IDS = {
  drift: 'door', entry: 'entry', shelf: 'shelf', reader: 'reader', tray: 'tray',
  list: 'list', browse: 'browse', 'srs-stats': 'progress', review: 'review',
  probe: 'probe', archive: 'archive', dojo: 'learn', deckplay: 'deckplay',
  contextdeck: 'contextdeck', personaldeck: 'personal', aiquiz: 'quiz',
  levels: 'reference', ai: 'tutor', lessons: 'lessons', mock: 'jlpt',
  kagami: 'progress', thesaurus: 'word-web', airead: 'personal-reading',
  feed: 'feed', publisher: 'publisher', 'source-inbox': 'source-inbox',
  'source-reader': 'source-reader', 'sentence-practice': 'sentence-practice',
  kanjidex: 'kanji', yoji: 'idioms', grammar: 'grammar', guided: 'guided',
  search: 'search', me: 'me', settings: 'settings',
};
const REGISTER_ROOM_DOORS = [['いまの日本を読む', 'news & magazines'], ['日本語を持ち込む', 'bring your own text'], ['参考書庫', 'Reference library'], ['レッスン', 'Lessons'], ['JLPT の練習', 'JLPT practice']];
const REGISTER_LINE_DOORS = [['読み物の好み', 'Reading preferences']];
function stampRegister() {
  const html = document.documentElement;
  const main = document.querySelector('#app > main');
  const room = ROOM_IDS[S.view] || S.view || 'door';
  const material = S.view === 'personaldeck' ? 'hall'
    : document.body.classList.contains('ginga') || !main ? 'door'
    : main.querySelector('.mock-opts, .mock-q, .guided-room[data-stage="question"]') ? 'attempt'
      : main.querySelector('.exam-confirm') ? 'threshold'
        : main.querySelector('.exam-score') ? 'results'
          : main.querySelector('.exam-levels') ? 'jlpt'
            : main.querySelector('.chat-log') ? 'tutor'
              : main.querySelector('#shelf-body') ? 'shelf'
                : main.querySelector('.mock-review') ? 'review' : 'hall';
  if (html.dataset.room !== room || html.dataset.register !== material) {
    html.dataset.room = room;
    html.dataset.register = material;
    // one beat of entrance motion on arrival only (register.css keys the lift on this)
    html.dataset.roomEntering = '1';
    clearTimeout(stampRegister.enterTimer);
    stampRegister.enterTimer = setTimeout(() => { delete html.dataset.roomEntering; }, 220);
  } else if (html.dataset.roomEntering) {
    // a re-render of the same room (a grade, a save, a tick) clears the marker before style
    // resolution, so only the arrival render's children animate
    clearTimeout(stampRegister.enterTimer);
    delete html.dataset.roomEntering;
  }
  // the older sets have no .exam-progress: their counter is the card-kind after the policy line
  const progress = document.querySelector('.exam-progress') ||
    document.querySelector('#app > main[data-mock-set] > .card-kind:not(.mock-attempt-policy)');
  const counted = ((progress?.firstElementChild || progress)?.textContent || '').match(/(\d+)\s*(?:of|\/)\s*(\d+)/);
  if (counted) html.style.setProperty('--stage', String(Number(counted[1]) / Number(counted[2])));
  else html.style.removeProperty('--stage');
  const opts = document.querySelector('.mock-opts, .mock-q + .lesson-options');
  if (opts?.querySelector('[aria-pressed="true"], [aria-checked="true"], .chosen, .selected, .is-selected')) html.dataset.answered = '1';
  else delete html.dataset.answered;
  for (const door of document.querySelectorAll('#shelf-body button.grammar-link:not([data-grade])')) {
    const label = (door.textContent || '').replace(/\s+/g, ' ').trim();
    door.dataset.grade = REGISTER_ROOM_DOORS.some((names) => label.toLowerCase().startsWith(tx(...names).toLowerCase())) ? 'room'
      : REGISTER_LINE_DOORS.some((names) => label.toLowerCase().startsWith(tx(...names).toLowerCase())) ? 'line' : 'tool';
  }
}

/** The visible state of a room that failed to draw. Keeps drafts; logs the fault. */
function renderRoomError(main, view, error) {
  console.error(`room ${view} failed to render`, error);
  const card = el('section', 'room-state room-error');
  card.dataset.roomError = view; card.setAttribute('role', 'alert');
  card.append(el('h1', 'view-title', tx('この部屋を開けませんでした', 'This room didn’t open')));
  card.append(el('p', '', tx('保存した記録はそのまま残っています。もう一度試すか、本棚に戻ってください。',
    'Nothing you saved is affected. Try again, or go back to the shelf.')));
  const retry = el('button', 'chip', tx('もう一度', 'Try again')); retry.type = 'button';
  retry.dataset.roomRetry = ''; retry.addEventListener('click', () => render());
  const home = el('button', 'chip', tx('本棚へ', 'To the shelf')); home.type = 'button';
  home.addEventListener('click', () => { S.view = 'shelf'; render(); });
  card.append(retry, home);
  main.append(card);
}
/* classes a press FLIPS — left out of the last-resort focus key, or the control could never be
 * found again by the very press that moved the keyboard */
const FOCUS_STATE_CLASSES = new Set(['on', 'on-list', 'dead', 'active', 'lit', 'primary', 'quiet']);
function render() {
  syncSheetActionVisit();
  if (personalHost) { personalHost.paint(); return; }
  if (retainedRetryView && S.view !== retainedRetryView) dropRetainedRetryRoute();
  // A pending collection belongs to this visit; a nested return frame may
  // retain it, but leaving the room cannot redirect a later overview visit.
  if (S.view !== 'levels') pendingReferenceCollection = null;
  // the word menu belongs to a word this render replaces
  closeReaderWordMenu();
  stopSentenceListening();
  stopAssessmentQuestionForRender();
  syncPracticeClock();
  if (lastRenderedView === 'feed' && S.view !== 'feed') publisherOpenRequest += 1;
  // leaving the JLPT room cancels any older-set start still downloading: returning later must
  // not replay a stale tap
  if (lastRenderedView === 'mock' && S.view !== 'mock') olderStartToken += 1;
  // leaving the guided session takes any moment off the glass; its progress is already saved
  if (lastRenderedView === 'guided' && S.view !== 'guided') guidedRoom?.suspend();
  removeMini();
  // Rebuilding #app empties the page for a moment, and the browser clamps
  // window scroll to 0 — so a double-tap for a gloss, opening a sheet, or
  // any other in-place re-render of the reader threw the walker back to
  // the top of the article. Snapshot before the rebuild; restore after,
  // for a same-view re-render of either reading surface — every view CHANGE
  // keeps its existing behaviour (callers set their own scroll, and cards
  // like review want the top of each new face).
  const restoreY = lastRenderedView === S.view && ['reader', 'airead', 'feed', 'publisher', 'source-inbox', 'source-reader', 'contextdeck'].includes(S.view) ? window.scrollY : null;
  // The same rebuild that clamps the scroll also throws focus back to
  // <body>, so a keyboard walker lost their place on EVERY state-changing
  // press — a dial, a grade, a capture (E3 round-A, a11y lens). Controls
  // that name themselves are found again by that name after the rebuild;
  // the sheet's own focus management still wins where it runs.
  const focusKey = (() => {
    const node = document.activeElement;
    if (!node || node === document.body || !$('#app').contains(node)) return null;
    if (node.id) return { sel: `#${CSS.escape(node.id)}` };
    const action = node.dataset?.action;
    if (action) return { sel: `[data-action="${CSS.escape(action)}"]` };
    // Last resort: the filter chips in 字引, 文法 and the dojo lobby name themselves no other
    // way, so every press dropped the keyboard to <body> (PR #77 1398bc2c). Such a control is
    // found by its shape, minus the state classes its own press flips, and by its own text
    // before its place — pressing a 部品 narrows the grid under the very chip pressed. Only
    // inside the room it was pressed in: a press that changed rooms (リストへ on the review
    // summary) would otherwise hand the keyboard to a stranger of the same shape (the tray's
    // 復習する, one Enter from a new review). And the text is a name only when no other
    // control of that shape wears it, or a repeated label went back to its first copy.
    if (lastRenderedView !== S.view) return null;
    const shape = [...node.classList].filter((name) => !FOCUS_STATE_CLASSES.has(name));
    if (!shape.length) return null;
    const sel = shape.map((name) => `.${CSS.escape(name)}`).join('');
    const all = [...$('#app').querySelectorAll(sel)];
    const ix = all.indexOf(node);
    if (ix < 0) return null;
    const text = (node.textContent || '').trim().slice(0, 16);
    const unique = all.filter((other) => (other.textContent || '').trim().slice(0, 16) === text).length === 1;
    return { sel, ix, text: unique ? text : null };
  })();
  const root = $('#app');
  root.textContent = '';
  document.body.classList.toggle('v-contrast-wcag', S.variants.contrast === 'wcag');
  document.body.classList.toggle('v-depth-layered', S.variants.depth === 'layered');
  // F/G ride across to the Drift layer, which owns the tap ladder itself. Sent
  // on every render (not only on a click) so the layer carries the strip's
  // reading whenever it finishes loading, and unknown values are ignored there.
  if (window.__DRIFT_TAP__)
    window.__DRIFT_TAP__.set({ ladder: S.variants.ladder, satTap: S.variants.sattap });
  document.body.classList.toggle('ui-bi', bi());
  // the reading measure is per-view: a column for the texts, the full window
  // for the landscapes (野 and 墨流し). CSS reads this, nothing else does.
  document.body.dataset.view = S.view;

  // 銀河 hero: at home on the drift the galaxy stands alone but for its symbol;
  // the ordinary top bar is replaced by the tap-to-open nav, and the drift's
  // own brand/depth/counters recede (CSS reads body.ginga). Inner pages — and
  // the drift with a sheet open — keep the normal chrome.
  const heroMode = S.ready && S.view === 'drift' && !S.stack.length;
  document.body.classList.toggle('ginga', heroMode);
  document.body.classList.toggle('ginga-open', heroMode && !!S.navOpen);
  if (!heroMode && S.navOpen) S.navOpen = false;
  if (heroMode) buildGingaChrome(root);

  // 復習 is zen: while a card is up, the whole world recedes — no top bar, no
  // crumb, no counters. Just the card, the answer, the four honest buttons.
  // The session summary at the end brings the ordinary room back.
  const focusLive = S.focus && !S.focus.ended && Date.now() < S.focus.deadline && S.focus.pool?.length;
  const zenReview =
    S.ready &&
    S.view === 'review' &&
    !!S.review &&
    !!scheduler &&
    !!fsrsApi &&
    (S.review.ix < S.review.queue.length || !!focusLive);
  // the probe room keeps the same glass: word up → world recedes
  const zenProbe = S.ready && S.view === 'probe' && !!S.probe && S.probe.ix < S.probe.queue.length;
  document.body.classList.toggle('zen', !!zenReview || !!zenProbe);
  if (!zenReview) S.reviewMore = false;

  const chrome = el('div', 'chrome');
  // the drift's spatial arbiter reads this tag: words recede under the top bar
  // instead of printing through it half-cut
  chrome.setAttribute('data-drift-chrome', '');
  const backBtn = biLabel('button', null, '戻る', 'back');
  backBtn.type = 'button';
  backBtn.id = 'back';
  const atHome =
    !S.stack.length &&
    (S.view === 'entry' || S.view === 'drift' || (S.view === 'shelf' && S.variants.entry === 'shelf'));
  backBtn.disabled = atHome;
  backBtn.addEventListener('click', back);
  chrome.append(backBtn);

  const crumb = el('div', 'crumb');
  const parts = [];
  // the crumb names the TRUE origin — the room 戻る actually reopens. The
  // dojo family (dojo, its probe, its focus blocks) is entered from the
  // galaxy and its backs walk galaxy-ward, never through the bookshelf.
  const dojoFamily = S.view === 'dojo' || S.view === 'probe' || S.view === 'deckplay' || (S.view === 'review' && S.focus) ||
    (S.view === 'guided' && guidedFrom === 'dojo');
  // the search room's door stands in the galaxy bar, and its Back walks
  // there unless it was opened from the shelf
  const searchFromGalaxy = S.view === 'search' && S.searchFrom !== 'shelf';
  // the lists tray opens from every room and its 戻る walks back there, so a room reached
  // through it (the tray, its quiz, a plain review) is rooted where the tray was opened —
  // it said 本棚 whichever room that was (PR #77 d9f0b984)
  const viaTray = S.view === 'tray' || S.view === 'aiquiz' || (S.view === 'review' && !S.focus);
  const trayOrigin = !viaTray ? null : S.trayFrom === 'reader' ? 'reader' : plainRecord(S.trayFrom) ? S.trayFrom.view : null;
  const galaxyWard = (view) => view === 'drift' || view === 'dojo' || view === 'probe' || view === 'deckplay' ||
    (view === 'guided' && guidedFrom === 'dojo') || (view === 'search' && S.searchFrom !== 'shelf');
  if (S.view === 'entry' || trayOrigin === 'entry') parts.push(tx('野', 'field'));
  else if (trayOrigin) parts.push(galaxyWard(trayOrigin) ? tx('銀河', 'galaxy') : tx('本棚', 'bookshelf'));
  else if (S.view === 'drift' || dojoFamily || searchFromGalaxy) parts.push(tx('銀河', 'galaxy'));
  else parts.push(tx('本棚', 'bookshelf'));
  if (S.view === 'reader' && passage()) {
    // an archive read names the stack it came from — its back door
    if (String(passage().file || '').startsWith('archive/')) parts.push(tx('新聞アーカイブ', 'archive'));
    parts.push(passage().title);
  }
  if (S.view === 'search') parts.push(tx('検索', 'search'));
  // the quiz and a plain review are entered from the lists tray and their 戻る reopens it — the
  // crumb named a bookshelf the press never touches (PR #77 ea8252a9, d9f0b984)
  if (viaTray) parts.push(tx('リスト', 'lists'));
  if (S.view === 'sentence-practice') parts.push(tx('文の練習', 'sentence practice'));
  if (S.view === 'review' && S.focus) parts.push(tx('集中道場', 'focus'));
  if (S.view === 'review') parts.push(tx(S.focus ? '集中' : '復習', S.focus ? 'focus block' : 'review'));
  if (S.view === 'dojo') parts.push(tx('集中道場', 'focus'));
  if (S.view === 'probe') parts.push(tx('集中道場', 'focus'), tx('読み探査', 'yomi probe'));
  if (S.view === 'archive') parts.push(tx('新聞アーカイブ', 'archive'));
  if (S.view === 'aiquiz') parts.push(tx('小テスト', 'quiz'));
  if (S.view === 'levels') parts.push(tx('参考書庫', 'reference library'));
  if (S.view === 'ai') parts.push(tx('先生', 'tutor'));
  if (S.view === 'lessons') parts.push(tx('レッスン', 'lessons'));
  if (S.view === 'mock') parts.push(tx('JLPT の練習', 'JLPT practice'));
  if (S.view === 'kagami') parts.push(tx('鏡', 'the mirror'));
  if (S.view === 'thesaurus') parts.push(tx('類語', 'synonyms'));
  if (S.view === 'airead') parts.push(tx('読み物', 'reading'));
  if (S.view === 'feed') parts.push(tx('ニュースと雑誌', 'news & magazines'));
  if (S.view === 'publisher') parts.push(tx('ニュースと雑誌', 'news & magazines'), tx('保存記事', 'saved article'));
  if (['source-inbox', 'source-reader'].includes(S.view)) parts.push(tx('持ち込んだ日本語', 'source inbox'));
  if (S.view === 'kanjidex') parts.push(tx('字引', 'kanji finder'));
  if (S.view === 'yoji') parts.push(tx('四字熟語', 'idioms'));
  if (S.view === 'grammar') parts.push(tx('文法', 'grammar'));
  if (S.view === 'guided') {
    parts.push(guidedFrom === 'mock' ? tx('JLPT の練習', 'JLPT practice') : tx('集中道場', 'focus'), tx('案内つきの稽古', 'guided session'));
  }
  if (S.view === 'contextdeck') parts.push(tx('文脈札', 'context deck'));
  if (S.view === 'deckplay') parts.push(tx('集中道場', 'focus'), tx('デッキ', 'deck'));
  for (const node of S.stack) parts.push(nodeTitle(node));
  crumb.title = parts.join(' › ');
  if (S.stack.length) crumb.dataset.uiContentValue = S.stack.map(nodeTitle).join('|');
  crumb.setAttribute('aria-label', crumb.title);
  crumb.append(el('b', null, parts.at(-1) || ''));
  crumb.dataset.currentRoom = S.view;
  // the reader names the level it is at in its own bar, beside the title (FEEL pass 2026-10-02)
  if (S.view === 'reader' && passage()) chrome.append(levelChip(passage(), 'chrome-level'));
  chrome.append(crumb);

  // the world seal, then EN | 日本語 — two visible states, the active one lit. The preferences
  // stand first in the right-hand cluster, the doors (search · Learn · Lists) after them.
  const seal = el('button', 'theme-seal', THEME_UI[themeIx()].seal);
  seal.type = 'button';
  seal.id = 'theme-seal';
  seal.setAttribute('aria-label', tx('世界を選ぶ', 'choose a world'));
  attachWorldPicker(seal);
  chrome.append(seal);

  const langSeg = el('div', 'lang-seg');
  langSeg.id = 'lang';
  langSeg.setAttribute('role', 'group');
  langSeg.setAttribute('aria-label', tx('表示言語', 'Interface language'));
  for (const [id, label] of [
    ['bi', 'EN'],
    ['ja', '日本語'],
  ]) {
    const b = el('button', null, label);
    b.type = 'button';
    b.dataset.lang = id;
    b.setAttribute('aria-pressed', String(S.lang === id));
    b.addEventListener('click', () => {
      S.lang = id;
      render();
    });
    langSeg.append(b);
  }
  chrome.append(langSeg);

  // the search door — on EVERY surface, one tap from hearing a word to
  // typing it (operator, 2026-08-27); only the search room itself omits it
  if (S.view !== 'search') {
    const quickSearch = el('button', 'chrome-search');
    quickSearch.type = 'button';
    quickSearch.id = 'chrome-search';
    quickSearch.setAttribute('aria-label', tx('検索 — ことばをさがす', 'search — look up a word'));
    quickSearch.innerHTML =
      SEARCH_SVG;
    quickSearch.addEventListener('click', () => {
      openSearchPage();
    });
    chrome.append(quickSearch);
  }

  // the dojo door — on EVERY surface (operator, 2026-09-17: "THE DOJO, or
  // study room, needs to be accessible from ANY LOCATION WHATSOEVER"). It
  // used to live only behind the galaxy's tap-to-open nav; now it stands in
  // the ordinary chrome beside the search door. Inside the dojo family it is
  // the current room, so it shows as such and does nothing.
  {
    const inDojo = S.view === 'dojo' || S.view === 'probe' || (S.view === 'review' && !!S.focus);
    // the polish lane (2026-10-08): the door is the Learn tab's room, so it carries the tab's
    // name (to a screen reader) and a quiet card-stack glyph — never a second word in the bar
    const dojoDoor = biLabel('button', 'chrome-dojo', '学ぶ', 'Learn');
    dojoDoor.type = 'button';
    dojoDoor.id = 'chrome-dojo';
    dojoDoor.insertAdjacentHTML('afterbegin', LEARN_DOOR_SVG);
    dojoDoor.setAttribute('aria-label', tx('学ぶ', 'Learn'));
    if (inDojo) dojoDoor.setAttribute('aria-current', 'page');
    dojoDoor.addEventListener('click', () => {
      if (inDojo) return;
      if (S.view === 'reader' && S.passageId) {
        clearTimeout(readerPosTimer);
        void saveReaderPosition(S.passageId, Math.round(window.scrollY));
      }
      keepScroll();
      S.navOpen = false;
      S.stack = [];
      S.view = 'dojo';
      render();
      window.scrollTo(0, 0);
    });
    chrome.append(dojoDoor);
  }

  // 覚える — the one capture button, top-right of every capture-eligible
  // surface (operator directive §3). The reader's takes the current thing:
  // the word last touched, carrying the sentence it was met in; its panel
  // holds the scope stages, the lists, and the way back out of a mis-tap.
  // Entry sheets carry their own seal in the sheet bar; surfaces with no
  // capturable current thing carry none.
  if (S.captureOpen && (S.stack.length || !readerTakeCurrent())) S.captureOpen = false;
  if (S.view === 'reader' && S.passageId) {
    const cur = readerTakeCurrent();
    const curTaken = !!cur && S.taken.some((t) => t.t === 'word' && t.id === cur.id);
    const capBtn = biLabel('button', curTaken ? 'chrome-take taken' : 'chrome-take', '覚える', 'memorize');
    capBtn.type = 'button';
    capBtn.id = 'reader-take';
    capBtn.disabled = !cur;
    capBtn.setAttribute('aria-pressed', String(curTaken));
    capBtn.setAttribute('aria-expanded', String(!!S.captureOpen));
    capBtn.setAttribute('aria-label', readerTakeLabel(cur, curTaken));
    holdReaderTakeSeal(capBtn, cur);
    capBtn.addEventListener('click', async () => {
      if (capBtn.disabled) return;
      const now = readerTakeCurrent();
      if (!now) return;
      // D11: a word the core dictionary lacks is never captured here; the
      // panel opens with the reason instead of the capture controls
      if (readerTakeHeld(now)) {
        S.captureOpen = true;
        render();
        return;
      }
      // D23: a spelling whose record answers as another entry opens the panel with the reason
      if (!S.taken.some((t) => t.t === 'word' && t.id === now.id) && wordCaptureState(readerTakeNode(now)) === 'conflict') {
        S.captureOpen = true;
        render();
        return;
      }
      S.captureOpen = false;
      // one press saves, as the popup's Save does; a press while saved takes it back out
      if (Date.now() - readerTakePressedAt < SAVE_PRESS_MS) return;
      readerTakePressedAt = Date.now();
      await toggleWordSave(readerTakeNode(now), now.id);
    });
    chrome.append(capBtn);
  }

  // Lists: a quiet bookmark and its count. The word stays in the door's text ("Lists 3" /
  // "覚 3") for a screen reader and the language law; on screen the glyph says it (polish lane)
  const trayBtn = biLabel('button', null, `覚 ${S.taken.length}`, `Lists ${S.taken.length}`);
  trayBtn.type = 'button';
  trayBtn.id = 'tray';
  {
    const label = trayBtn.querySelector('.l-ja');
    const word = el('span', 'tray-word', tx('覚', 'Lists'));
    label.replaceChildren(word, document.createTextNode(' '), el('span', 'tray-count', String(S.taken.length)));
    trayBtn.dataset.count = String(S.taken.length);
  }
  trayBtn.addEventListener('click', () => {
    keepScroll();
    S.stack = [];
    // the tray remembers its door — WHICHEVER door it was. It is the one
    // control present in the chrome of every surface, so returning always to
    // the shelf threw away the archive year-list, the levels room, the
    // lessons list… every room but the reader (E3 round-A, dead-ends lens).
    // The origin is the view and its offset, not a single special case.
    S.trayFrom =
      S.view === 'reader' && S.passageId
        ? 'reader'
        : S.view !== 'tray'
          ? { view: S.view, scroll: Math.round(window.scrollY) }
          : null;
    if (S.trayFrom === 'reader') {
      // readerPos bookmark — UI preference, not learner evidence (P0-4
      // residual-ledger disposition, same as the reader's own two writers)
      clearTimeout(readerPosTimer);
      void saveReaderPosition(S.passageId, Math.round(window.scrollY));
    }
    S.view = 'tray';
    render();
    // every other room door lands at its own top; the one door present on
    // EVERY surface did not, so the tray opened at the previous surface's
    // offset — often past its own end (E3 round-A, dead-ends lens)
    window.scrollTo(0, 0);
  });
  chrome.append(trayBtn);
  if (!heroMode && !zenReview) root.append(chrome);
  buildPrimaryTabs(root);

  // the capture panel — anchored under the chrome's top-right seal. It
  // reuses the sheet's own instruments verbatim: the reversible 覚える
  // button, the scope stages (語だけ・この文・段落), and the list picker
  // with its inline maker — so the door and the deep flow never disagree.
  if (S.captureOpen) {
    const cur = readerTakeCurrent();
    const capNode = readerTakeNode(cur);
    const panel = el('div', 'capture-panel');
    panel.id = 'capture-panel';
    panel.setAttribute('role', 'group');
    panel.setAttribute('aria-label', tx(`「${cur.id}」を覚える`, `memorize ${cur.id}`));
    panel.setAttribute('data-drift-chrome', '');
    const head = el('div', 'capture-head');
    head.append(el('span', 'capture-word', cur.id));
    head.append(el('span', 'pool-tag', tx(NODE_KIND.word[0], NODE_KIND.word[1])));
    panel.append(head);
    if (readerTakeHeld(cur)) {
      // D11: a held word shows why, and offers nothing that could capture it
      panel.setAttribute('aria-label', tx(`「${cur.id}」はここで覚えられない`, `${cur.id} cannot be memorized here`));
      const reason = el('p', 'reader-choice-capture', readerCaptureReasonText(cur.id));
      reason.id = 'reader-take-reason';
      panel.append(reason);
    } else {
      panel.append(takeButton(capNode, cur.id));
      renderWordCaptureNote(panel, capNode, cur.id);
      renderContextPicker(panel, capNode);
      renderListPicker(panel, capNode, cur.id);
    }
    root.append(panel);
    requestAnimationFrame(() => {
      const bar = document.querySelector('.chrome');
      if (bar && panel.isConnected) panel.style.top = `${Math.ceil(bar.getBoundingClientRect().bottom + 8)}px`;
    });
  }

  const main = el('main');
  // a page change cross-fades in (FEEL pass 2026-10-02); a re-render of the same room never fades
  if (lastRenderedView && lastRenderedView !== S.view) main.dataset.enter = '1';
  root.append(main);

  if (!S.ready) {
    main.append(el('div', 'loading', tx('回廊 をひらいています…', 'opening the corridor…')));
    renderVariants(root);
    safelySyncStoreAlert();
    stampRegister();
    syncPaper();
    return;
  }

  // The Drift universe sleeps unless it is the active view — its layer sits
  // beneath the corridor chrome, so the one navigation fabric stays visible.
  // It also sleeps under an open entry sheet: the layer is a sibling of #app,
  // so the inert pass below cannot reach it, and its six window-level pointer
  // listeners would read every tap on the sheet as a tap on open water and
  // raze the constellation underneath. Sleeping is not forgetting — the stack,
  // the centre and its satellites are all held in the layer's own state, so
  // closing the sheet hands the field back exactly as it was left.
  if (window.__DRIFT__) {
    syncDriftTheme();
    // …and a page nobody is looking at is a room they have left: the galaxy is the
    // default entry, and its loop held the main thread even in a background tab
    // (PR #77 ef524842). The same public seam the view switch uses; nothing reaches in.
    if (S.view === 'drift' && !S.stack.length && !document.hidden) window.__DRIFT__.show();
    else window.__DRIFT__.hide();
  }

  // the interim voice belongs to the reader: leaving the room ends it
  if (S.view !== 'reader') { stopReadAloud(); readerTipVisit = null; }
  // The context deck's focus state belongs only to its own room.
  if (S.view !== 'contextdeck') delete document.documentElement.dataset.cdFocus;

  // A room that throws must never leave an empty page: that is how a blank
  // room reached the learner with no message (2026-09-24).
  try {
    if (S.view === 'drift') renderDrift(main);
    else if (S.view === 'entry') renderEntry(main);
    else if (S.view === 'reader') renderReader(main);
    else if (S.view === 'tray') renderTray(main);
    else if (S.view === 'list') renderListPage(main);
    else if (S.view === 'browse') renderBrowse(main);
    else if (S.view === 'srs-stats') renderSrsStats(main);
    else if (S.view === 'review') renderReview(main);
    else if (S.view === 'probe') renderProbe(main);
    else if (S.view === 'archive') renderArchive(main);
    else if (S.view === 'dojo') renderFocus(main);
    else if (S.view === 'deckplay') renderDeckPlay(main);
    else if (S.view === 'aiquiz') renderAiQuiz(main);
    else if (S.view === 'levels') renderLevels(main);
    else if (S.view === 'ai') renderAiSetup(main);
    else if (S.view === 'lessons') renderLessons(main);
    else if (S.view === 'mock') renderMock(main);
    else if (S.view === 'kagami') renderKagami(main);
    else if (S.view === 'thesaurus') renderThesaurus(main);
    else if (S.view === 'airead') renderAiReading(main);
    else if (S.view === 'feed') renderFeed(main);
    else if (S.view === 'publisher') renderPublisherReading(main);
    else if (S.view === 'source-inbox') renderSourceInbox(main);
    else if (S.view === 'source-reader') renderSourceReading(main);
    else if (S.view === 'sentence-practice') renderSentencePractice(main);
    else if (S.view === 'kanjidex') renderKanjidex(main);
    else if (S.view === 'yoji') renderYoji(main);
    else if (S.view === 'grammar') renderGrammar(main);
    else if (S.view === 'guided') renderGuided(main);
    else if (S.view === 'contextdeck') renderContextDeck(main);
    else if (S.view === 'search') { renderSearchPage(main); renderWordsDoors(main); }
    else if (S.view === 'me') renderMe(main);
    else if (S.view === 'settings') renderSettings(main);
    else renderShelf(main);
  } catch (error) {
    main.replaceChildren();
    renderRoomError(main, S.view, error);
  }
  // the room's vertical sign hangs first in the page, floated into its right margin
  { const sign = main.querySelector('.room-error') ? null : buildRoomSign(); if (sign) main.prepend(sign); }
  // after the room, never inside its stage: the focused stage keeps its composition and every
  // state (probe, unavailable card, error) keeps a report entry one scroll away
  if (maintenanceReports && S.view !== 'drift') root.append(reportEntries('report-line-page'));

  renderSheet(root);
  renderStrokePage(root);
  renderFocusHud(root);
  renderVariants(root);
  enhanceJapaneseProse(root);

  // Exactly one layer is live at a time. 筆順 sits above the sheet, so when it
  // is open even the sheet goes inert — nothing behind the top layer is
  // reachable by finger, keyboard, or screen reader.
  if (S.strokes || S.stack.length) {
    for (const child of root.children) {
      const live = S.strokes
        ? child.id === 'stroke-page'
        : child.id === 'sheet' || child.classList.contains('scrim');
      if (live) {
        child.inert = false;
        child.removeAttribute('aria-hidden');
        continue;
      }
      child.inert = true;
      child.setAttribute('aria-hidden', 'true');
    }
  }
  // Resolve the new room's styles before store-alert positioning reads layout.
  stampRegister();
  safelySyncStoreAlert();
  updateMeasurements();
  if (restoreY != null) window.scrollTo(0, restoreY);
  // give the keyboard its place back, if the control that had it still
  // exists under the same name. A sheet or the writing room manages its own
  // focus and must not be overruled, so this only reaches into #app, and it
  // never steals focus from whatever the rebuild legitimately moved it to.
  if (focusKey && document.activeElement === document.body) {
    const all = focusKey.ix == null ? [] : [...$('#app').querySelectorAll(focusKey.sel)];
    const named = focusKey.text == null ? [] : all.filter((node) => (node.textContent || '').trim().slice(0, 16) === focusKey.text);
    const again = focusKey.ix == null ? $('#app').querySelector(focusKey.sel)
      : (named.length === 1 ? named[0] : null) || all[focusKey.ix];
    if (again && typeof again.focus === 'function') again.focus({ preventScroll: true });
  }
  lastRenderedView = S.view;
  // Sample the resolved ground after both the view classes and room stamp settle.
  syncPaper();
  retireCardAudioOnFaceChange();
  // every navigation passes through here — keep the Back sentinel honest
  syncWalkSentinel();
}

// Operational reports have their own outbox and recipient. Never export the
// learner record, provider settings, chat, answers or source text implicitly.
const maintenanceNavigation = [];
function maintenanceContext() {
  let selected = null;
  try { selected = S.view === 'mock' ? currentAssessmentV2() : null; } catch { /* Boot may be incomplete. */ }
  const itemId = selected?.attempt?.cursor?.itemId;
  const detail = S.stack.at(-1);
  const contentIds = [itemId, S.passageId, S.strokes?.id ? `kanji:${S.strokes.id}` : null,
    detail?.id ? `${detail.t}:${detail.id}` : null,
    detail?.reading ? `reading:${detail.reading}` : null]
    .filter(value => typeof value === 'string' && value.length <= 160);
  const surface = String(S.view || 'loading').slice(0, 80);
  if (maintenanceNavigation.at(-1)?.target !== surface) {
    maintenanceNavigation.push({ action: 'view', target: surface });
    if (maintenanceNavigation.length > 12) maintenanceNavigation.shift();
  }
  return {
    surface: `corridor/${surface}${S.strokes ? '/strokes' : detail ? `/detail/${detail.t}` : ''}`,
    route: location.pathname,
    content_ids: contentIds,
    content_revision: selected?.form?.revisionId || null,
    viewport: { width: innerWidth, height: innerHeight },
    locale: S.lang === 'ja' ? 'ja' : 'en',
    action_trace: maintenanceNavigation.slice(),
  };
}
let maintenanceReports = null;
let olderStartToken = 0;
/** The report entry lives in the page's own flow — never a layer over its controls. */
function reportEntries(className) {
  const line = el('p', `report-line ${className || ''}`.trim());
  const open = el('button', 'report-door', tx('問題を報告', 'Report a problem')); open.type = 'button';
  // WebKit does not focus a clicked button; take focus first so closing the report returns here
  open.dataset.reportEntry = 'open'; open.addEventListener('click', () => { open.focus({ preventScroll: true }); maintenanceReports?.openReport(); });
  const list = el('button', 'report-door', tx('送った報告', 'My reports')); list.type = 'button';
  list.dataset.reportEntry = 'list'; list.addEventListener('click', () => { list.focus({ preventScroll: true }); maintenanceReports?.openReports(); });
  line.append(open, list);
  return line;
}
function mountMaintenanceReports() {
  if (!window.BunkiReports) return;
  maintenanceReports = window.BunkiReports.mount({
    rail: true,
    serviceUrl: window.__BUNKI_MAINTENANCE_URL__ || (location.protocol === 'http:' || location.protocol === 'https:' ? location.origin : ''),
    getContext: maintenanceContext,
    clockNotice: () => {
      try { const selected = currentAssessmentV2(); return selected?.attempt?.status === 'in-progress' && selected.attempt.mode === 'timed' ? 'The test clock continues while this report is open.' : ''; }
      catch { return ''; }
    },
    protectAnswers: () => {
      try { const selected = currentAssessmentV2(); return selected?.attempt?.status === 'in-progress' && selected.attempt.mode === 'timed'; }
      catch { return false; }
    },
  });
}

window.addEventListener('DOMContentLoaded', () => {
  mountMaintenanceReports();
  boot().catch((err) => {
    document.body.dataset.error = String(err);
    const root = $('#app');
    root.textContent = '';
    root.append(el('div', 'loading', `読み込めなかった could not load: ${err.message}`));
    // a learner whose app will not start is exactly who needs to say so
    if (maintenanceReports) root.append(reportEntries('report-line-page'));
  });
});

/* ---- 集中道場 › デッキ: the host lexicon adapter the deck player receives
 * (decks/player/host.js; learning-design §3). Kept below the storage-ledger
 * line pins on purpose (residual-storage-callers.json): the two call sites
 * above changed in place, so no pinned line moved. The adapter is closures
 * over this module's own lexicon, entry sheets and one-tap save: a tap on a
 * deck card is capture, never evidence, so nothing here writes the
 * observation log or any schedule, and taking a word never enrols it in the
 * deck. The single-file build cannot import it and mounts no deck anyway. */
let deckHostModule = null;
let deckHostAdapter = null;
function loadDeckHost() {
  if (deckHostModule || window.__CORRIDOR_STANDALONE__ === true) return Promise.resolve(deckHostModule);
  return import('./decks/player/host.js').then(
    (mod) => (deckHostModule = mod),
    () => null, // the deck still opens, with furigana only
  );
}

function deckHost() {
  if (!deckHostModule) return null;
  if (!deckHostAdapter) {
    const norm = (p) => String(p || '').replace(/[〜～\s（）()]/g, '');
    deckHostAdapter = deckHostModule.createHost({
      word: (id, reading) => lookup(id, null, reading),
      kanji: (glyph) => D.kanji?.[glyph] || null,
      grammar: (id, pattern) =>
        GRAMMARS().find((g) => g.id === id) || (pattern ? GRAMMARS().find((g) => norm(g.p) === norm(pattern)) : null) || null,
      open: (node) => go(node),
      taken: () => S.taken,
      // 覚える from a deck card is the corridor's one save path (STANDARD A51): the same one-tap
      // save, Saved toast and 元に戻す as the reader's dictionary visit, into the shared review
      // pool; no chooser. A row already held for this identity is left as it is, never toggled off.
      capture: (node, label) => (wordCaptureState(node) === 'taken' ? true : toggleWordSave(node, label)),
      addToList: (node, label, invoker) => openVocabularyListPopover(node, label, invoker),
    });
  }
  return deckHostAdapter;
}
